rebuild/2008-06/tests/g3d_native_batch_r.text:
"""Check G3D native sources, and queue uncertain matches for review.

Run without arguments for G3D. For libpng discovery use --discover-only
--c-recipe libpng-1.2.5 --prefix Png5. Discovered identities remain review-only.
The native runner checks source freshness, bytes, data, direct bindings and
imports before indexing. Compiler variants are diagnostic, not proofs.
"""
import argparse
import hashlib
import json
import os
from pathlib import Path
import re
import struct
import subprocess
import sys

from capstone import Cs, CS_ARCH_X86, CS_MODE_32, CS_GRP_CALL, CS_GRP_JUMP
from capstone.x86 import X86_OP_IMM, X86_OP_MEM, X86_OP_REG, X86_INS_MOV
import native_check_runner as runner


def prepare(analysis, identities):
    decoder = Cs(CS_ARCH_X86, CS_MODE_32)
    decoder.detail = True
    imports = runner.import_evidence()[0]
    jobs, unresolved = [], []
    for result in analysis:
        if result.get('status', 'complete') != 'complete':
            unresolved.append({'source': result.get('source'), 'reason': result.get('error', 'compile failed')})
            continue
        raw = Path(result['object']).read_bytes()
        sections, symbols, definitions, _ = runner.match._coff_data_index(raw)
        checks = []
        for row in result['checks']:
            if row.get('status') != 'exact':
                unresolved.append({'address': row['addr'], 'reason': row.get('status', 'missing'),
                                   'metrics': row.get('metrics'),
                                   'contiguous_catch_comparison': row.get('contiguous_catch_comparison')})
                continue
            address = int(row['addr'], 16)
            target, _, _ = runner.match.target('2008-06', row['addr'])
            start, section = definitions[row['symbol']]
            table = sections[section]
            refs = {}
            for i in range(table[7]):
                offset, index, kind = struct.unpack_from('<IIH', raw, table[5] + 10 * i)
                refs[offset - start] = (symbols[index][0], kind)
            calls = []
            instructions = list(decoder.disasm(target, address))
            for ins in instructions:
                op = ins.operands[0] if ins.operands else None
                external_jump = (ins.group(CS_GRP_JUMP) and op and
                                 (op.type != X86_OP_IMM or not address <= op.imm < address + len(target)))
                if not ins.group(CS_GRP_CALL) and not external_jump:
                    continue
                off = ins.address - address
                operand = op
                ref = refs.get(off + 1)
                item = None
                if operand.type == X86_OP_IMM and ref and ref[1] == 20:
                    dest = f'{operand.imm & 0xffffffff:08x}'
                    if dest in identities.get(ref[0], []):
                        item = {'offset': off, 'target': dest, 'symbol': ref[0], 'kind': 'jump' if external_jump else 'direct'}
                elif not external_jump and operand.type == X86_OP_MEM and not operand.mem.base and not operand.mem.index:
                    dest = operand.mem.disp & 0xffffffff
                    ref = refs.get(off + 2)
                    if ref and ref[1] == 6 and dest in imports:
                        item = {'offset': off, 'target': f'{dest:08x}', 'symbol': ref[0],
                                'kind': 'import', 'import': imports[dest]}
                elif not external_jump and operand.type == X86_OP_REG:
                    register = ins.reg_name(operand.reg)
                    loads = []
                    for load in instructions:
                        if load.address >= ins.address or load.id != X86_INS_MOV or len(load.operands) != 2:
                            continue
                        dst, src = load.operands
                        if (dst.type != X86_OP_REG or load.reg_name(dst.reg) != register or src.type != X86_OP_MEM
                                or src.mem.base or src.mem.index or load.disp_size != 4):
                            continue
                        load_offset = load.address - address
                        dest = src.mem.disp & 0xffffffff
                        ref = refs.get(load_offset + load.disp_offset)
                        if (ref and ref[1] == 6 and dest in imports and
                                runner.register_import_flow(target, address, load_offset, off, register)):
                            loads.append({'offset': off, 'load_offset': load_offset, 'target': f'{dest:08x}',
                                          'symbol': ref[0], 'kind': 'import_reg', 'import': imports[dest]})
                    if len(loads) == 1:
                        item = loads[0]
                if item:
                    calls.append(item)
                else:
                    unresolved.append({'address': row['addr'], 'offset': off,
                                       'instruction': ins.mnemonic + ' ' + ins.op_str,
                                       'candidate': ref[0] if ref else None})
            checks.append({'addr': row['addr'], 'symbol': row['symbol'], 'calls': calls})
        jobs.append({'source': result['source'], 'checks': checks})
    return {'jobs': jobs}, unresolved


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    base = Path(__file__).resolve().parent
    parser.add_argument('analysis', type=Path, nargs='?', default=base / 'g3d_native_batch_plan.json')
    parser.add_argument('identities', type=Path, nargs='?', default=base / 'g3d_native_batch_identities.json',
                        help='reviewed symbol -> list of original addresses')
    parser.add_argument('manifest', type=Path, nargs='?', default=runner.ROOT / 'work/2008-06/shared-layouts/g3d-batch-review.json')
    parser.add_argument('--run', action='store_true', help='compile input manifest, verify and index passing checks')
    parser.add_argument('--prepare-only', action='store_true', help='read prior analysis and write review manifest only')
    parser.add_argument('--no-variants', action='store_true', help='skip three bounded compiler-profile trials')
    parser.add_argument('--no-discovery', action='store_true', help='only run the explicitly listed plan')
    parser.add_argument('--discover-only', action='store_true', help='only run discovered review-only targets')
    parser.add_argument('--namespace', default='G3D')
    parser.add_argument('--prefix', default='G3D')
    parser.add_argument('--c-recipe', help='discover a C library recipe, e.g. libpng-1.2.5')
    parser.add_argument('--c-symbol-prefix', default='_png_')
    args = parser.parse_args()
    execute = args.run or (args.analysis == base / 'g3d_native_batch_plan.json' and not args.prepare_only)
    check_runner = Path(__file__).with_name('native_check_runner.py')

    def invoke(*arguments, env=None):
        done = subprocess.run([sys.executable, str(check_runner), *map(str, arguments)],
                              capture_output=True, text=True, env=env)
        print(done.stdout, end='')
        if done.returncode:
            raise RuntimeError(done.stderr or 'native checker failed')
        for line in reversed(done.stdout.splitlines()):
            try:
                value = json.loads(line)
            except ValueError:
                continue
            if isinstance(value, dict) and value.get('results'):
                return Path(value['results'])
        raise RuntimeError('native checker did not report results')

    manual = set()
    inactive = None
    if execute:
        plan = json.loads(args.analysis.read_text(encoding='utf-8-sig'))
        if not args.no_discovery and (args.discover_only or args.analysis == base / 'g3d_native_batch_plan.json'):
            import native_target_discovery as discovery
            from roc.integration_site import inactive_code
            data = json.loads((runner.ROOT / 'docs/data/2008-06.json').read_text(encoding='utf-8'))
            inactive = inactive_code(runner.ROOT)
            found = (discovery.discover_c(data, args.c_recipe, args.c_symbol_prefix, args.prefix, inactive)
                     if args.c_recipe else discovery.discover(data, args.namespace, args.prefix, inactive, True))
            jobs = {} if args.discover_only else {
                str((runner.BASE / j['source']).resolve() if not Path(j['source']).is_absolute() else Path(j['source']).resolve()).casefold(): j
                for j in plan['jobs']}
            for job in found['jobs']:
                key = str(Path(job['source']).resolve()).casefold()
                if key not in jobs:
                    jobs[key] = job
                else:
                    present = {c['addr'].lower().removeprefix('0x').zfill(8) for c in jobs[key]['checks']}
                    jobs[key]['checks'].extend(c for c in job['checks'] if c['addr'] not in present)
            plan = {'jobs': list(jobs.values())}
            args.analysis = args.manifest.with_name(args.manifest.stem + '-expanded-plan.json')
            args.analysis.write_text(json.dumps(plan, indent=2) + '\n')
            print('Discovered', sum(len(j['checks']) for j in found['jobs']), 'review-only candidates', flush=True)
        manual = {(c['addr'].lower().removeprefix('0x').zfill(8), c['symbol'])
                  for job in plan['jobs'] for c in job.get('checks', []) if c.get('review_only')}
    analysis = invoke('run', args.analysis, '--workers', '3') if execute else args.analysis
    run_results = analysis
    if execute:
        scans = {str((runner.BASE / j['source']).resolve() if not Path(j['source']).is_absolute()
                     else Path(j['source']).resolve()).casefold(): j for j in plan['jobs'] if j.get('scan_scopes')}
        if scans:
            if inactive is None:
                from roc.integration_site import inactive_code
                inactive = inactive_code(runner.ROOT)
            proposals = {}
            for result in json.loads(run_results.read_text()):
                spec = scans.get(str(Path(result['source']).resolve()).casefold())
                if not spec:
                    continue
                for coverage in result.get('coverage', []):
                    for hit in coverage.get('hits', []):
                        if hit['size'] < 64 or inactive.get(hit['addr'], [None, False])[1]:
                            continue
                        symbols = [s for s in hit['symbols'] if any(scope in s for scope in spec['scan_scopes'])]
                        if len(symbols) == 1:
                            proposals[(result['source'], hit['addr'])] = symbols[0]
            if proposals:
                for job in plan['jobs']:
                    source = str((runner.BASE / job['source']).resolve() if not Path(job['source']).is_absolute()
                                 else Path(job['source']).resolve())
                    existing = {c['addr'].lower().removeprefix('0x').zfill(8) for c in job.get('checks', [])}
                    for (owner, addr), symbol in proposals.items():
                        if owner.casefold() == source.casefold() and addr not in existing:
                            job.setdefault('checks', []).append({'addr': addr, 'symbol': symbol, 'review_only': True})
                            manual.add((addr, symbol))
                scoped = args.manifest.with_name(args.manifest.stem + '-range-plan.json')
                scoped.write_text(json.dumps(plan, indent=2) + '\n')
                analysis = invoke('analyze', run_results.parent, '--manifest', scoped)
                print('Range discovery:', len(proposals), 'review-only candidates', flush=True)
    manifest, missing = prepare(json.loads(analysis.read_text()), json.loads(args.identities.read_text()))
    if execute:
        reviewed = {}
        for job in plan['jobs']:
            source = (runner.BASE / job['source']).resolve() if not Path(job['source']).is_absolute() else Path(job['source']).resolve()
            for check in job.get('checks', []):
                if 'references' in check:
                    key = (str(source).casefold(), check['addr'].lower().removeprefix('0x').zfill(8))
                    if key in reviewed:
                        raise ValueError('duplicate reviewed reference declarations')
                    reviewed[key] = check['references']
        for job in manifest['jobs']:
            for check in job['checks']:
                refs = reviewed.get((str(Path(job['source']).resolve()).casefold(), check['addr']))
                if refs is not None:
                    check['references'] = refs
    args.manifest.write_text(json.dumps(manifest, indent=2) + '\n')
    indexed, variants = [], []
    if execute:
        checked = invoke('analyze', analysis.parent, '--manifest', args.manifest)
        passing = json.loads(checked.read_text())
        builds = {row['source']: row for row in json.loads(run_results.read_text())}
        if not args.no_variants:
            for build in builds.values():
                failures = [row for row in build.get('checks', []) if row.get('status') == 'different'
                            and (row['addr'], row['requested_symbol']) not in manual
                            and not row.get('contiguous_catch_comparison', {}).get('relocation_normalized_match')]
                if not failures:
                    continue
                source = Path(build['source'])
                found = re.search(r'^// native-flags: (.*)$', source.read_text(encoding='utf-8-sig'), re.M)
                if not found:
                    continue
                trial_plan = args.manifest.with_name(args.manifest.stem + '-variants.json')
                trial_plan.write_text(json.dumps({'jobs': [{'source': str(source), 'checks': [
                    {'addr': row['addr'], 'symbol': row['requested_symbol']} for row in failures]}]}, indent=2) + '\n')
                for switch in ('/Ob0', '/Ob1', '/fp:precise'):
                    env = dict(os.environ, NATIVE_FLAGS=found.group(1) + ' ' + switch)
                    trial = invoke('run', trial_plan, '--workers', '1', env=env)
                    for job in json.loads(trial.read_text()):
                        for row in job.get('checks', []):
                            variants.append({'address': row['addr'], 'switch': switch, 'status': row['status'],
                                             'metrics': row.get('metrics'), 'run': str(trial)})
        for job, result in zip(manifest['jobs'], passing):
            if job['source'] != result['source']:
                raise RuntimeError('source order changed during review')
            if result.get('changed_inputs'):
                missing.append({'source': result['source'], 'reason': 'build inputs changed during analysis'})
                continue
            passed = {row['addr'] for row in result['checks']
                      if row.get('status') == 'exact' and not row.get('data_errors')
                      and row.get('call_identity', {}).get('passed')
                      and row.get('reference_identity', {}).get('passed')}
            for row in result['checks']:
                if row['addr'] not in passed and row['addr'] not in {x.get('address') for x in missing}:
                    missing.append({'address': row['addr'], 'reason': 'data, call, or byte verification failed',
                                    'unresolved_references': [r for r in row.get('reference_identity', {}).get('references', [])
                                                              if r.get('status') == 'unresolved_reference']})
            checks = [row for row in job['checks'] if row['addr'] in passed
                      and (row['addr'], row['symbol']) not in manual]
            for row in job['checks']:
                if (row['addr'], row['symbol']) in manual:
                    missing.append({'address': row['addr'], 'reason': 'discovered identity needs review'})
            if not checks:
                continue
            source_sha = runner.sha(Path(result['source']))
            build = builds[result['source']]
            key = hashlib.sha256(json.dumps({'source': result['source'], 'source_sha256': source_sha,
                'dependencies': build['dependencies'], 'flags': build['flags'],
                'compiler': build['build_inputs']['compiler'], 'checks': checks,
                'runner': runner.sha(check_runner), 'original': runner.sha(runner.ROOT / 'clients/2008-06/Roblox.exe')},
                sort_keys=True).encode()).hexdigest()[:24]
            isolated = args.manifest.with_name(args.manifest.stem + '-' + key + '.json')
            isolated.write_text(json.dumps({'jobs': [{'source': job['source'], 'checks': checks}]}, indent=2) + '\n')
            receipt = runner.ROOT / 'work/2008-06/shared-layouts' / ('g3d-batch-' + key + '.json')
            if receipt.exists():
                previous = json.loads(receipt.read_text())
                if (previous.get('source_sha256') != source_sha or
                    {row['address'] for row in previous.get('checks', []) if row.get('exact')} != {row['addr'] for row in checks}):
                    raise RuntimeError('existing receipt does not match this batch: ' + str(receipt))
            else:
                invoke('analyze', analysis.parent, '--manifest', isolated, '--require-proof', '--index-output', receipt)
            indexed.extend(row['addr'] for row in checks)
    report = {'manifest': str(args.manifest), 'indexed': indexed, 'unresolved': missing,
              'variants': variants, 'variant_scope': 'diagnostic only; verify source, calls and chosen build flags before indexing'}
    report_path = args.manifest.with_name(args.manifest.stem + '-report.json')
    report_path.write_text(json.dumps(report, indent=2) + '\n')
    print(json.dumps({'indexed': indexed, 'review_functions': sorted({x.get('address', x.get('source')) for x in missing}),
                      'report': str(report_path)}, indent=2))


if __name__ == '__main__':
    main()

rebuild/2008-06/tests/native_check_runne.text:
"""Background native diagnostics: compile each source once, reuse isolated objects.

start MANIFEST launches hidden background work; status RUN reads a compact receipt.
run MANIFEST runs in foreground. analyze RUN [--manifest MANIFEST] compares the
recorded objects again WITHOUT compiling. Add --index-output PATH to analyze one
reviewed source and write a new inactive receipt only if all proof checks pass.
PATH must be a new JSON file in work/2008-06/shared-layouts. Manifest: {"jobs":[{"source":
"native-classes/Foo.cpp","checks":[{"addr":"00500000","symbol":"?foo@"}],
"ranges":["00500000-00510000"],"layouts":[{"addr":"00500000","symbol":"?foo@",
"thiscall":true}]}]}. Source paths relative to rebuild/2008-06; other CLI paths
relative to cwd. Three workers default. No cross-run compile cache, client run,
link, server match or P5/P6 gate. Range hits prove masked bytes, not identity.
Optional manifest compiler_build selects 21022 (default) or 50727; the recorded
compiler is retained during analysis. Optional compiler_variant="rtm" selects
the installed VS2005 RTM toolchain instead of the default detected 50727 release.
"""
import argparse
from concurrent.futures import ThreadPoolExecutor, as_completed
import hashlib
import json
import os
from pathlib import Path
import re
import subprocess
import struct
import sys
import time
import uuid

ROOT = Path(__file__).resolve().parents[3]
BASE = ROOT / 'rebuild/2008-06'
RUNS = ROOT / 'work/2008-06/native-check-runs'
sys.path.insert(0, str(ROOT))
from roc import libs, match, rebuild, native_work


# Original IWorkspace COM slots (IDispatch + SaveToFile/SaveSelectionToFile).
# See record_native_workspace_save.py; verify the original slot before trusting a label.
METHOD_IDENTITIES = {
    '?SaveToFile@CWorkspace@@UAGJPA_W@Z': ('0046c780', 0x80ae88),
    '?SaveSelectionToFile@CWorkspace@@UAGJPA_W@Z': ('0046b8d0', 0x80ae8c),
}


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def save(path, value):
    temporary = path.with_name(path.name + '.' + uuid.uuid4().hex + '.tmp')
    temporary.write_text(json.dumps(value, indent=2) + '\n', encoding='utf-8')
    try:
        for attempt in range(10):
            try:
                os.replace(temporary, path)
                break
            except PermissionError as error:
                if getattr(error, 'winerror', None) != 5 or attempt == 9:
                    raise
                time.sleep(0.05 * (attempt + 1))
    finally:
        temporary.unlink(missing_ok=True)


def compiler_build(data):
    build = data.get('compiler_build', 21022)
    if type(build) is not int or build not in (21022, 50727):
        raise ValueError('compiler_build must be 21022 or 50727')
    return build


def compiler_variant(data):
    variant = data.get('compiler_variant', 'default')
    if variant not in ('default', 'rtm') or (variant == 'rtm' and compiler_build(data) != 50727):
        raise ValueError('compiler_variant must be default or 50727 rtm')
    return variant


def selected_toolchain(data):
    build = compiler_build(data)
    variant = compiler_variant(data)
    tc = rebuild.toolchain(build)
    if variant == 'rtm':
        vc = ROOT / 'tools/vc2005/Program Files/Microsoft Visual Studio 8/VC'
        tc.update(cl=vc / 'bin/cl.exe', link=vc / 'bin/link.exe', lib=vc / 'bin/lib.exe',
                  vc_include=vc / 'include', vc_lib=vc / 'lib', crt=vc / 'lib/msvcrt.lib',
                  mspdb=vc.parent / 'Common7/IDE/mspdb80.dll')
        if not tc['cl'].is_file() or not tc['vc_include'].is_dir():
            raise ValueError('VS2005 RTM compiler or headers unavailable')
    return tc


def jobs_from(data):
    jobs = {}
    if not data.get('jobs'):
        raise ValueError('manifest needs nonempty jobs')
    for item in data['jobs']:
        source = (BASE / item['source']).resolve()
        if not source.is_file():
            raise ValueError('missing source: ' + str(source))
        job = jobs.setdefault(str(source).casefold(), {'source': str(source), 'checks': [], 'ranges': [], 'layouts': []})
        for field in ('checks', 'ranges', 'layouts'):
            for value in item.get(field, []):
                if field == 'ranges':
                    lo, hi = (int(s, 16) for s in value.split('-'))
                    if lo >= hi:
                        raise ValueError('range needs LO < HI')
                else:
                    int(value['addr'], 16)
                    if not value.get('symbol'):
                        raise ValueError('check/layout needs symbol')
                    if field == 'layouts' and value.get('thiscall') is not True:
                        raise ValueError('layout needs explicit thiscall=true')
                if value not in job[field]:
                    job[field].append(value)
    return list(jobs.values())


def compiler_flags(source, override=None):
    recipe = libs.RECIPES['rbxgs']
    headers = str(BASE / 'native-headers')
    pinned = re.search(r'^// native-flags: (.*)$', source.read_text(encoding='utf-8-sig'), re.M)
    profile = override or os.environ.get('NATIVE_FLAGS') or (pinned[1] if pinned else '/O2 /Ob2 /Oy /GF /GS- /EHsc /MD /D_AFXDLL /DNDEBUG /D_MBCS')
    flags = ['/nologo', '/c'] + profile.replace('{headers}', headers).split()
    # Runner owns output paths; reject overrides that could collide with other work.
    if any(flag.lower().startswith(('/fo', '/fd', '/yc', '/yu'))
           or flag.lower().startswith('/fp') and not flag.lower().startswith('/fp:')
           or flag.lower().startswith('/fa') and not flag.lower().startswith('/favor:')
           or flag.startswith('@') for flag in flags):
        raise ValueError('profile output/PCH/response flags unsupported in isolated runner')
    flags = ['/DBOOST_ALL_NO_LIB'] + ['/D' + v for v in recipe['defines'].split()] + flags
    flags += ['/I' + headers, '/I' + str(ROOT / 'tools/libs/mfc-9.0-rtm/atlmfc/include')]
    flags += ['/I' + str((libs.LIBS / v).resolve()) for v in recipe['include'] if v != 'WINSDK']
    return flags + ['/D_XTP_STATICLINK', '/D_XTPLIB_NOAUTOLINK', '/I' + str(ROOT / 'tools/libs/xtp-11.2.2/Source')]


def import_evidence():
    """Read PE import names and configured VC9 CRT/SDK import-library aliases."""
    from roc import clients
    import pefile
    image = clients.exe_path('2008-06', clients.load()['2008-06'])
    image_data = image.read_bytes()
    hashes = {str(image): hashlib.sha256(image_data).hexdigest()}
    pe = pefile.PE(data=image_data, fast_load=True)
    pe.parse_data_directories(directories=[pefile.DIRECTORY_ENTRY['IMAGE_DIRECTORY_ENTRY_IMPORT']])
    labels = {}
    for descriptor in getattr(pe, 'DIRECTORY_ENTRY_IMPORT', []):
        dll = descriptor.dll.decode('ascii')
        for entry in descriptor.imports:
            if entry.name is None:
                continue  # Ordinal imports need their own independent proof.
            if entry.address in labels:
                raise ValueError('Duplicate PE import address')
            labels[entry.address] = dll + '!' + entry.name.decode('ascii')
    pe.close()
    aliases = {}
    directory = ROOT / 'tools/vc2008rtm/Program Files/Microsoft Visual Studio 9.0/VC/lib'
    paths = [directory / name for name in ('msvcrt.lib', 'msvcprt.lib')]
    sdk = rebuild.toolchain(21022).get('sdk_lib')
    if sdk:
        for name in ('Kernel32.Lib', 'WS2_32.Lib', 'Advapi32.Lib', 'OleAut32.Lib'):
            path = Path(sdk) / name
            if path.is_file():
                paths.append(path)
    # Resolve ordinal-only SDK imports against the actual 32-bit DLL exports.
    ordinal_exports = {}
    for name in ('ws2_32', 'oleaut32'):
        dll_path = Path(os.environ.get('SystemRoot', r'C:\Windows')) / 'SysWOW64' / (name + '.dll')
        if dll_path.is_file() and any(p.name.lower() == name + '.lib' for p in paths):
            data = dll_path.read_bytes()
            dll = pefile.PE(data=data, fast_load=True)
            if dll.FILE_HEADER.Machine == 0x14c:
                dll.parse_data_directories(directories=[pefile.DIRECTORY_ENTRY['IMAGE_DIRECTORY_ENTRY_EXPORT']])
                ordinal_exports[name + '.dll'] = {entry.ordinal: entry.name.decode('ascii')
                                                  for entry in dll.DIRECTORY_ENTRY_EXPORT.symbols if entry.name}
                hashes[str(dll_path)] = hashlib.sha256(data).hexdigest()
            dll.close()
    for path in paths:
        data = path.read_bytes()
        hashes[str(path)] = hashlib.sha256(data).hexdigest()
        if not data.startswith(b'!<arch>\n'):
            raise ValueError('Invalid CRT import library: ' + str(path))
        offset = 8
        while offset + 60 <= len(data):
            size = int(data[offset + 48:offset + 58])
            member = data[offset + 60:offset + 60 + size]
            offset += 60 + size + (size & 1)
            if member[:4] != b'\0\0\xff\xff':
                continue
            symbol, dll = member[20:].split(b'\0')[:2]
            symbol, dll = symbol.decode('ascii'), dll.decode('ascii').lower()
            name_type = (struct.unpack_from('<H', member, 18)[0] >> 2) & 7
            if name_type == 0 and dll in ordinal_exports:
                ordinal = struct.unpack_from('<H', member, 16)[0]
                export = ordinal_exports[dll].get(ordinal)
                if not export or symbol.lstrip('_@').split('@', 1)[0] != export:
                    continue
            elif name_type == 1:
                export = symbol
            elif name_type in (2, 3):
                export = symbol[1:] if symbol[:1] in ('_', '@', '?') else symbol
                if name_type == 3:
                    export = export.split('@', 1)[0]
            else:
                continue
            aliases.setdefault((dll, export), set()).add('__imp_' + symbol)
    return labels, aliases, hashes


def check_noncall_refs(raw, symbol, body, target, data_refs, calls, expected, address=None):
    """Account for every absolute relocation, including globals and callbacks.

    Reviewed call imports are covered by the separate call proof. Read-only
    local constants must compare in full and contain no nested relocations.
    Other pointers require an explicit independently reviewed identity.
    """
    from capstone import Cs, CS_ARCH_X86, CS_MODE_32
    sections, symbols, definitions, _ = match._coff_data_index(raw)
    start, section = definitions[symbol]
    table = sections[section]
    declarations = {row['offset']: row for row in expected}
    if len(declarations) != len(expected):
        raise ValueError('duplicate reference expectation offset')
    covered = set()
    decoder = Cs(CS_ARCH_X86, CS_MODE_32)
    decoder.detail = True
    instructions = {i.address: i for i in decoder.disasm(target, 0)}
    for call in calls:
        if call.get('kind') == 'import':
            covered.add(call['offset'] + 2)
        elif call.get('kind') == 'import_reg':
            load = instructions.get(call.get('load_offset'))
            if load and load.disp_size == 4:
                covered.add(call['load_offset'] + load.disp_offset)
    constants = {off: (off, data, inner) for off, data, inner in data_refs
                 if 0 <= off and off + 4 <= len(target)}
    rows, imports = [], None
    for i in range(table[7]):
        offset, index, kind = struct.unpack_from('<IIH', raw, table[5] + 10 * i)
        off = offset - start
        if kind != 6 or not 0 <= off < len(body):
            continue
        name, value, number, _ = symbols[index]
        if off in covered:
            rows.append({'offset': off, 'symbol': name, 'status': 'verified_call_import'})
            continue
        actual = int.from_bytes(target[off:off + 4], 'little') if off + 4 <= len(target) else None
        if (address is not None and number - 1 == section and actual is not None and off + 4 <= len(body)
                and address <= actual < address + len(body)):
            addend = struct.unpack_from('<i', body, off)[0]
            if actual == (address + value - start + addend) & 0xffffffff:
                rows.append({'offset': off, 'symbol': name, 'status': 'verified_local_code_label'})
                continue
        if name.startswith('__imp_') and actual is not None and body[off:off + 4] == b'\0\0\0\0':
            if imports is None:
                imports = import_evidence()
            label = imports[0].get(actual, '')
            dll, separator, export = label.partition('!')
            if separator and name in imports[1].get((dll.lower(), export), set()):
                rows.append({'offset': off, 'symbol': name, 'target': f'{actual:08x}', 'status': 'verified_data_import'})
                continue
        local = constants.get(off)
        if local and number > 0 and not sections[number - 1][9] & 0x80000000 and not local[2] and address is not None:
            matches, errors = match.data_check('2008-06', f'{address:08x}', target, [local])
            if len(matches) == 1 and not errors:
                rows.append({'offset': off, 'symbol': name, 'status': 'verified_readonly_data'})
                continue
        wanted = declarations.pop(off, None)
        ok = bool(wanted and wanted.get('evidence') and wanted.get('symbol') == name
                  and actual == int(wanted['target'], 16) and body[off:off + 4] == b'\0\0\0\0')
        rows.append({'offset': off, 'symbol': name, 'target': f'{actual:08x}' if actual is not None else None,
                     'status': 'verified_reviewed_reference' if ok else 'unresolved_reference'})
    return {'passed': not declarations and all(row['status'] != 'unresolved_reference' for row in rows),
            'references': rows, 'unused_expectations': list(declarations.values()),
            'import_evidence_inputs': imports[2] if imports else {},
            'scope': 'Absolute relocations only; provider selection, ABI and runtime remain separate.'}


def register_import_flow(target, address, load_offset, call_offset, register):
    """Conservatively prove a callee-saved register holds one import at a call.

    Reject unmodelled branches, paths bypassing the load, writes, and calls to
    anything else after the load. Callers must separately verify the IAT load.
    """
    from capstone import Cs, CS_ARCH_X86, CS_MODE_32, CS_GRP_CALL, CS_GRP_JUMP, CS_GRP_RET
    from capstone.x86 import X86_OP_IMM, X86_OP_MEM, X86_OP_REG, X86_INS_JMP, X86_INS_MOV
    aliases = {'edi': {'edi', 'di'}, 'esi': {'esi', 'si'}, 'ebx': {'ebx', 'bx', 'bl', 'bh'}}
    if register not in aliases:
        return False
    decoder = Cs(CS_ARCH_X86, CS_MODE_32)
    decoder.detail = True
    instructions = {i.address: i for i in decoder.disasm(target, address)}
    load = instructions.get(address + load_offset)
    call = instructions.get(address + call_offset)
    if not load or load.id != X86_INS_MOV or len(load.operands) != 2:
        return False
    dst, src = load.operands
    if (dst.type != X86_OP_REG or load.reg_name(dst.reg) != register or src.type != X86_OP_MEM
            or src.mem.base or src.mem.index):
        return False
    if (not call or not call.group(CS_GRP_CALL) or call.operands[0].type != X86_OP_REG
            or call.reg_name(call.operands[0].reg) != register):
        return False
    pending, seen, reached = [(address, False)], set(), False
    while pending:
        pc, valid = pending.pop()
        if (pc, valid) in seen:
            continue
        seen.add((pc, valid))
        ins = instructions.get(pc)
        if ins is None:
            return False
        if pc == address + call_offset:
            reached = True
            if not valid:
                return False
        if pc == address + load_offset:
            valid = True
        elif ins.group(CS_GRP_CALL):
            op = ins.operands[0]
            if op.type != X86_OP_REG or ins.reg_name(op.reg) != register:
                valid = False
        elif any(ins.reg_name(reg) in aliases[register] for reg in ins.regs_access()[1]):
            valid = False
        if ins.group(CS_GRP_RET):
            continue
        next_pc = pc + ins.size
        if ins.group(CS_GRP_JUMP):
            if ins.operands[0].type != X86_OP_IMM:
                return False
            pending.append((ins.operands[0].imm & 0xffffffff, valid))
            if ins.id != X86_INS_JMP:
                pending.append((next_pc, valid))
        else:
            pending.append((next_pc, valid))
    return reached


def check_calls(raw, symbol, body, target, address, expected):
    """Check reviewed direct calls, tail jumps and identified IAT calls.

    Direct rows specify offset, original target and exact COFF symbol. Import
    rows additionally specify kind=import and the original DLL!export. Their
    PE IAT address and CRT import-library alias must both agree. Dynamic or
    virtual calls, final provider selection and callee ABI remain unproven.
    """
    from capstone import Cs, CS_ARCH_X86, CS_MODE_32, CS_GRP_CALL, CS_GRP_JUMP
    from capstone.x86 import X86_OP_IMM, X86_OP_MEM, X86_OP_REG
    sections, symbols, definitions, _ = match._coff_data_index(raw)
    start, section = definitions[symbol]
    table = sections[section]
    refs = {}
    for index in range(table[7]):
        offset, name, kind = struct.unpack_from('<IIH', raw, table[5] + 10 * index)
        if start <= offset < start + len(body):
            refs[offset - start] = (symbols[name][0], kind)
    decoder = Cs(CS_ARCH_X86, CS_MODE_32)
    decoder.detail = True
    declarations = {row['offset']: row for row in expected}
    if len(declarations) != len(expected):
        raise ValueError('duplicate call expectation offset')
    imports = import_evidence() if any(row.get('kind') in ('import', 'import_reg') for row in expected) else None
    instructions = {i.address - address: i for i in decoder.disasm(target, address)}
    rows = []
    for instruction in decoder.disasm(target, address):
        offset = instruction.address - address
        op = instruction.operands[0] if instruction.operands else None
        external_jump = (instruction.group(CS_GRP_JUMP) and
                         (op.type != X86_OP_IMM or not address <= op.imm < address + len(target)))
        jump = (instruction.group(CS_GRP_JUMP)
                and (external_jump or declarations.get(offset, {}).get('kind') == 'jump'))
        if not instruction.group(CS_GRP_CALL) and not jump:
            continue
        wanted = declarations.pop(offset, None)
        direct = instruction.operands[0].type == X86_OP_IMM
        destination = instruction.operands[0].imm if direct else None
        binding = refs.get(offset + 1)
        ok = bool(direct and (not wanted or wanted.get('kind', 'direct') == 'direct')
                  and instruction.bytes[0] == 0xe8 and binding and binding[1] == 20
                  and wanted and binding[0] == wanted['symbol']
                  and destination == int(wanted['target'], 16)
                  and body[offset + 1:offset + 5] == b'\0\0\0\0')
        kind = 'direct'
        if jump:
            kind = 'jump'
            ok = bool(wanted and direct and instruction.bytes[0] == 0xe9
                      and body[offset:offset + 1] == b'\xe9'
                      and body[offset + 1:offset + 5] == b'\0\0\0\0'
                      and binding and binding[1] == 20 and binding[0] == wanted['symbol']
                      and destination == int(wanted['target'], 16))
        if wanted and wanted.get('kind') == 'import':
            kind = 'import'
            binding = refs.get(offset + 2)
            op = instruction.operands[0]
            absolute = (op.type == X86_OP_MEM and op.mem.base == 0 and op.mem.index == 0)
            destination = op.mem.disp & 0xffffffff if absolute else None
            label = imports[0].get(destination) if absolute else None
            expected_label = wanted.get('import', '')
            dll, separator, export = expected_label.partition('!')
            actual_dll, actual_separator, actual_export = (label or '').partition('!')
            ok = bool(absolute and bytes(instruction.bytes[:2]) == b'\xff\x15'
                      and body[offset:offset + 2] == b'\xff\x15'
                      and body[offset + 2:offset + 6] == b'\0\0\0\0'
                      and binding and binding[1] == 6 and binding[0] == wanted['symbol']
                      and destination == int(wanted['target'], 16)
                      and separator and actual_separator and dll.lower() == actual_dll.lower()
                      and export == actual_export
                      and binding[0] in imports[1].get((dll.lower(), export), set()))
        if wanted and wanted.get('kind') == 'import_reg':
            kind = 'import_reg'
            load_offset = wanted.get('load_offset')
            load = instructions.get(load_offset) if isinstance(load_offset, int) else None
            op = instruction.operands[0]
            reg = instruction.reg_name(op.reg) if op.type == X86_OP_REG else None
            load_op = load.operands[1] if load and len(load.operands) == 2 else None
            absolute = bool(load_op and load_op.type == X86_OP_MEM and not load_op.mem.base and not load_op.mem.index)
            destination = load_op.mem.disp & 0xffffffff if absolute else None
            binding = refs.get(load_offset + load.disp_offset) if absolute else None
            label = imports[0].get(destination) if absolute else None
            dll, separator, export = wanted.get('import', '').partition('!')
            actual_dll, actual_separator, actual_export = (label or '').partition('!')
            field = load_offset + load.disp_offset if absolute else -1
            ok = bool(absolute and load.disp_size == 4 and binding and binding[1] == 6
                      and binding[0] == wanted['symbol'] and destination == int(wanted['target'], 16)
                      and separator and actual_separator and dll.lower() == actual_dll.lower() and export == actual_export
                      and binding[0] in imports[1].get((dll.lower(), export), set())
                      and body[load_offset:field] == bytes(load.bytes[:load.disp_offset])
                      and body[field:field + 4] == b'\0\0\0\0'
                      and body[field + 4:load_offset + load.size] == bytes(load.bytes[load.disp_offset + 4:])
                      and body[offset:offset + instruction.size] == bytes(instruction.bytes)
                      and register_import_flow(target, address, load_offset, offset, reg))
        rows.append({'offset': offset, 'target': f'{destination:08x}' if destination is not None else None,
                     'symbol': binding[0] if binding else None, 'kind': kind,
                     'status': ('verified_import' if kind in ('import', 'import_reg') else 'verified_binding') if ok
                               else 'unresolved_or_wrong_binding'})
    if imports:
        for file, digest in imports[2].items():
            if sha(Path(file)) != digest:
                raise ValueError('CRT import library changed during analysis: ' + file)
    return {'passed': not declarations and all(row['status'] in ('verified_binding', 'verified_import') for row in rows),
            'calls': rows, 'unused_expectations': list(declarations.values()),
            'import_evidence_inputs': imports[2] if imports else {},
            'scope': 'Reviewed direct calls, explicitly declared tail jumps and IAT bindings only; dynamic calls, provider selection and callee ABI require separate proof.'}


def analyze_object(job, obj):
    raw = obj.read_bytes()
    bodies = match.coff_functions(raw)
    checks, coverage, layouts = [], [], []
    for check in job['checks']:
        check_started = time.monotonic()
        addr = f"{int(check['addr'], 16):08x}"
        target, refs, _ = match.target('2008-06', addr)
        found = [b for b in bodies if b[0] == check['symbol']] or [b for b in bodies if b[0].startswith(check['symbol'])]
        row = {'addr': addr, 'requested_symbol': check['symbol'], 'status': 'missing'}
        if len(found) > 1:
            row.update(status='ambiguous', candidates=[f[0] for f in found])
        elif found:
            name, body, relocs = found[0]
            exact = set(refs) <= set(relocs) and match.exact_match(target, refs, body, relocs)
            metrics = match.comparison_metrics(target, refs, body, relocs)
            row.update(symbol=name, status='exact' if exact else 'different',
                       score=100.0 if exact else min(99.999999, metrics['fuzzy_percent']),
                       legacy_score=match.score(target, refs, body, relocs), metrics=metrics,
                       target_size=len(target), object_size=len(body), target_sha256=hashlib.sha256(target).hexdigest())
            masked = set(refs) | set(relocs)
            row['first_byte_difference'] = next((i for i in range(min(len(target), len(body)))
                if not any(r <= i < r + 4 for r in masked) and target[i] != body[i]),
                min(len(target), len(body)) if len(target) != len(body) else None)
            if len(target) < len(body) <= 65536:
                _, symbols, definitions, _ = match._coff_data_index(raw)
                start, section = definitions[name]
                catch_prefix = '__catch$' + name + '$'
                has_catch = any(s.startswith(catch_prefix) and n == section + 1
                                and start + len(target) <= value < start + len(body)
                                for s, value, n, _ in symbols.values())
                if has_catch:
                    base, image = match._image('2008-06')
                    va = int(addr, 16)
                    offset = va - base
                    if 0 <= offset and offset + len(body) <= len(image):
                        extended = bytes(image[offset:offset + len(body)])
                        extended_refs = [r - va for r in match._base_relocs('2008-06')
                                         if va <= r < va + len(body)]
                        row['contiguous_catch_comparison'] = {
                            'scope': 'diagnostic contiguous bytes only; not a function boundary, reference, or runtime proof',
                            'relocation_normalized_match': set(extended_refs) <= set(relocs) and
                                match.exact_match(extended, extended_refs, body, relocs),
                            'metrics': match.comparison_metrics(extended, extended_refs, body, relocs),
                        }
            identity = METHOD_IDENTITIES.get(name)
            if identity:
                expected, slot = identity
                image_base, image = match._image('2008-06')
                original = struct.unpack_from('<I', image, slot - image_base)[0]
                passed = addr == expected and original == int(expected, 16)
                row['method_identity'] = dict(expected=expected, vtable_slot=f'{slot:08x}',
                                              original_slot_target=f'{original:08x}', passed=passed)
                if not passed:
                    row.update(status='method_identity_mismatch', masked_byte_score=row['score'], score=0)
                    exact = False
            if exact:
                data_refs = match.coff_data_refs(raw, name)
                data_matches, data_errors = match.data_check('2008-06', addr, target, data_refs)
                row.update(data_matches=data_matches, data_errors=data_errors)
                if 'calls' in check:
                    row['call_identity'] = check_calls(raw, name, body, target, int(addr, 16), check['calls'])
                    row['reference_identity'] = check_noncall_refs(raw, name, body, target, data_refs,
                                                                  check['calls'], check.get('references', []), int(addr, 16))
        row['check_seconds'] = round(time.monotonic() - check_started, 6)
        if 'metrics' in row:
            m = row['metrics']
            print(f"SCORE {addr} status={row['status']} score={row['score']:.6f} "
                  f"positional={m['positional_percent']} raw={m['raw_positional_percent']} "
                  f"diff={m['unmasked_differences']}/{m['compared_unmasked_bytes']} "
                  f"bytes={m['candidate_bytes']}/{m['target_bytes']} delta={m['length_delta']:+d} "
                  f"reloc_missing={len(m['missing_relocations'])} reloc_extra={len(m['extra_relocations'])}", flush=True)
            if 'contiguous_catch_comparison' in row:
                extra = row['contiguous_catch_comparison']
                m = extra['metrics']
                print(f"CATCH_RANGE {addr} match={extra['relocation_normalized_match']} "
                      f"fuzzy={m['fuzzy_percent']} positional={m['positional_percent']} "
                      f"raw={m['raw_positional_percent']} "
                      f"diff={m['unmasked_differences']}/{m['compared_unmasked_bytes']} "
                      f"bytes={m['candidate_bytes']}/{m['target_bytes']} (diagnostic only)", flush=True)
        checks.append(row)
    if job['ranges']:
        functions = [json.loads(line) for line in (ROOT / 'work/2008-06/functions.jsonl').read_text().splitlines()]
        for interval in job['ranges']:
            lo, hi = (int(v, 16) for v in interval.split('-'))
            hits, missing = [], []
            for function in functions:
                addr = function['addr']
                if not lo <= int(addr, 16) < hi or function.get('kind', 'code') != 'code':
                    continue
                target, refs, _ = match.target('2008-06', addr)
                names = [name for name, body, relocs in bodies if len(body) == len(target) and set(refs) <= set(relocs) and match.exact_match(target, refs, body, relocs)]
                if names:
                    hits.append({'addr': addr, 'symbols': names, 'size': len(target)})
                else:
                    missing.append({'addr': addr, 'size': len(target)})
            coverage.append({'range': interval, 'hits': hits, 'missing': missing,
                             'scope': 'masked-byte analogs; symbol identity and call bindings unproven'})
    if job['layouts']:
        import native_layout_evidence as layout
        for check in job['layouts']:
            hits = [b for b in bodies if b[0] == check['symbol']] or [b for b in bodies if b[0].startswith(check['symbol'])]
            if len(hits) != 1:
                raise ValueError('layout symbol missing/ambiguous: ' + check['symbol'])
            name, body, refs = hits[0]
            address = int(check['addr'], 16)
            target, target_refs, _ = match.target('2008-06', f'{address:08x}')
            original, candidate = layout.extract(target, address, target_refs), layout.extract(body, address, refs)
            layouts.append({'addr': check['addr'], 'symbol': name, 'target': original, 'candidate': candidate,
                            'comparison': layout.compare(original, candidate),
                            'call_obligations': layout.call_obligations(raw, name, body, refs, target, target_refs, address),
                            'scope': layout.__doc__})
    return {'checks': checks, 'coverage': coverage, 'layouts': layouts}


def build_inputs(tc):
    compiler = Path(tc['cl']) if tc.get('cl') else None
    paths = [compiler] + [compiler.with_name(name) for name in ('c1.dll', 'c1xx.dll', 'c2.dll')] if compiler else []
    if tc.get('mspdb'):
        paths.append(Path(tc['mspdb']))
    return dict(compiler={str(p): sha(p) for p in paths if p.is_file()},
                includes={k: str(tc[k]) if tc.get(k) else None for k in ('vc_include', 'atlmfc_include', 'sdk_include')})


def build_changes(receipt, tc):
    changed = []
    if not receipt.get('build_inputs'):
        changed.append('build configuration unrecorded; historical evidence only')
    elif receipt['build_inputs'] != build_inputs(tc):
        changed.append('compiler/toolchain inputs changed')
    # An explicit current override selects a new configuration. Otherwise reuse
    # the captured override, even after the original shell environment ended.
    override = os.environ.get('NATIVE_FLAGS') or receipt.get('native_flags')
    if compiler_flags(Path(receipt['source']), override) != receipt.get('flags'):
        changed.append('compiler flags changed')
    return changed


def compile_job(job, folder, tc):
    folder.mkdir()
    started = time.time_ns()
    clock = time.monotonic()
    source = Path(job['source'])
    result = {'source': str(source), 'status': 'failed', 'object': str(folder / 'candidate.obj')}
    try:
        exhausted = native_work.over_budget(job.get('checks', []))
        if exhausted:
            result['error'] = 'function budget exhausted; park or finish session: ' + ', '.join(exhausted)
            return result
        before = sha(source)
        flags = compiler_flags(source)
        result.update(build_inputs=build_inputs(tc), native_flags=os.environ.get('NATIVE_FLAGS'))
        compile_started = time.monotonic()
        code, log = rebuild.run(tc, 'cl', flags + ['/showIncludes', '/Fo' + result['object'], '/Fd' + str(folder / 'compiler.pdb'), str(source)], folder)
        result['compile_seconds'] = round(time.monotonic() - compile_started, 3)
        (folder / 'compile.log').write_text(log, encoding='utf-8')
        result.update(compiler_exit=code, source_sha256=before, flags=flags, log=str(folder / 'compile.log'))
        if code:
            result['error'] = 'compiler failed; see compile.log'
            return result
        dependencies = {source}
        for line in log.splitlines():
            hit = re.match(r'\s*Note: including file:\s*(.*?)\s*$', line)
            if hit:
                dependencies.add(Path(hit[1]).resolve())
        result['dependencies'] = {str(p): sha(p) for p in sorted(dependencies)}
        # Fingerprints are evidence, not a cache key. No reuse of changed builds.
        changed = [str(p) for p in dependencies if p != source and p.stat().st_mtime_ns >= started]
        changed += build_changes(result, tc)
        if sha(source) != before or changed:
            result.update(error='inputs changed during compile; rerun', changed_inputs=changed)
            return result
        obj = Path(result['object'])
        result['object_sha256'] = sha(obj)
        analysis_started = time.monotonic()
        result.update(analyze_object(job, obj), status='complete')
        result['analysis_seconds'] = round(time.monotonic() - analysis_started, 3)
        return result
    except Exception as error:
        result['error'] = f'{type(error).__name__}: {error}'
        return result
    finally:
        result['seconds'] = round(time.monotonic() - clock, 3)
        save(folder / 'receipt.json', result)


def compact(results):
    checks = [row for result in results if result['status'] == 'complete' for row in result.get('checks', [])]
    ranges = {}
    for result in results:
        for coverage in result.get('coverage', []):
            group = ranges.setdefault(coverage['range'], {'functions': {}, 'hits': set()})
            for row in coverage['hits'] + coverage['missing']:
                group['functions'][row['addr']] = row['size']
            group['hits'].update(row['addr'] for row in coverage['hits'])
    return {'compiled_sources': len(results), 'failed_sources': sum(r['status'] != 'complete' for r in results),
            'compile_seconds_sum': round(sum(r.get('compile_seconds', 0) for r in results), 3),
            'analysis_seconds_sum': round(sum(r.get('analysis_seconds', 0) for r in results), 3),
            'exact_checks': sum(r['status'] == 'exact' for r in checks), 'checks': len(checks),
            'data_checked': sum('data_errors' in r for r in checks),
            'verified_checks': sum(r['status'] == 'exact' and 'data_errors' in r and not r['data_errors'] for r in checks),
            'binding_verified_checks': sum(r['status'] == 'exact' and 'data_errors' in r and not r['data_errors']
                                           and r.get('call_identity', {}).get('passed', False) for r in checks),
            'data_mismatches': [r for r in checks if r.get('data_errors')][:8],
            'issues': [{'source': r['source'], 'error': r['error']} for r in results if r.get('error')][:8],
            'mismatches': [r for r in checks if r['status'] != 'exact'][:8],
            'coverage': [{'range': interval, 'matched_functions': len(group['hits']), 'functions': len(group['functions']),
                          'matched_bytes': sum(group['functions'][addr] for addr in group['hits']),
                          'scope': 'masked-byte analogs, not identity proof'} for interval, group in ranges.items()]}


def execute(run, workers):
    # Exclusive claim: two foreground/background workers never share a run.
    with (run / 'claim').open('x') as claim:
        claim.write(str(os.getpid()))
    data = json.loads((run / 'manifest.json').read_text())
    jobs = data['jobs']
    headers = native_work.headers()
    save(run / 'shared-headers.json', headers)
    summary = {'state': 'running', 'pid': os.getpid(), 'run': str(run), 'total_sources': len(jobs), 'completed_sources': 0,
               'observer_sha256': sha(Path(__file__)), 'manifest_sha256': sha(run / 'manifest.json'),
               'work_log_sha256': sha(native_work.__file__),
               'timing_log': str(run / 'function-timings.jsonl'),
               'scope': 'local diagnostics only; fresh compile per source, no ABI/server/P5/P6 gate proof; complete means finished; inspect exact_checks and data_mismatches'}
    save(run / 'summary.json', summary)
    started, results = time.monotonic(), []
    try:
        build = compiler_build(data)
        tc = selected_toolchain(data)
        summary['compiler_build'] = build
        summary['compiler_variant'] = compiler_variant(data)
        summary['compiler'] = str(tc['cl'])
        summary['compiler_sha256'] = sha(tc['cl'])
        with ThreadPoolExecutor(max_workers=workers) as pool:
            futures = {pool.submit(compile_job, job, run / f'unit-{index:03}', tc): index for index, job in enumerate(jobs)}
            for future in as_completed(futures):
                result = future.result()
                result['unit'] = futures[future]
                results.append(result)
                summary.update(completed_sources=len(results), **compact(results))
                summary['updated_at_ns'] = time.time_ns()
                save(run / 'summary.json', summary)
        drift = native_work.changed(headers, native_work.headers())
        for result in results:
            dependencies = result.get('dependencies', {})
            changed = [p for p, digest in dependencies.items() if not Path(p).exists() or sha(p) != digest]
            if drift or changed:
                result.update(status='failed', changed_inputs=sorted(set(drift + changed)),
                              error='inputs changed across batch; do not accept mixed-header evidence')
        summary.update(**compact(results), shared_headers_changed=drift)
        summary['state'] = 'failed' if any(r['status'] != 'complete' for r in results) else 'complete'
    except Exception as error:
        summary.update(state='failed', error=f'{type(error).__name__}: {error}')
    summary['seconds'] = round(time.monotonic() - started, 3)
    for result in results:
        native_work.log_checks(run, jobs[result['unit']], result)
    summary['results'] = str(run / 'results.json')
    save(run / 'results.json', sorted(results, key=lambda r: r['unit']))
    save(run / 'summary.json', summary)
    return summary


def alive(pid):
    if os.name != 'nt':
        try:
            os.kill(pid, 0)
            return True
        except ProcessLookupError:
            return False
        except PermissionError:
            return None
    import ctypes
    from ctypes import wintypes
    kernel = ctypes.WinDLL('kernel32', use_last_error=True)
    kernel.OpenProcess.argtypes = [wintypes.DWORD, wintypes.BOOL, wintypes.DWORD]
    kernel.OpenProcess.restype = wintypes.HANDLE
    kernel.GetExitCodeProcess.argtypes = [wintypes.HANDLE, ctypes.POINTER(wintypes.DWORD)]
    kernel.CloseHandle.argtypes = [wintypes.HANDLE]
    handle = kernel.OpenProcess(0x1000, False, pid)
    if not handle:
        return None if ctypes.get_last_error() == 5 else False
    try:
        code = wintypes.DWORD()
        if not kernel.GetExitCodeProcess(handle, ctypes.byref(code)):
            return None
        return code.value == 259
    finally:
        kernel.CloseHandle(handle)


def display(run):
    summary = json.loads((run / 'summary.json').read_text())
    launcher = run / 'launcher.json'
    pid = summary.get('pid') or (json.loads(launcher.read_text())['pid'] if launcher.exists() else None)
    if summary['state'] in ('queued', 'running') and pid and alive(pid) is False:
        summary = json.loads((run / 'summary.json').read_text())
        if summary['state'] in ('queued', 'running'):
            summary.update(state='failed', error='worker exited without terminal receipt; inspect worker.log')
    print(json.dumps(summary, separators=(',', ':')))
    return summary


def index_inactive(results, receipts, tc, output, analysis_path):
    """Index one explicitly reviewed, fully bound native source without overwriting receipts."""
    require_proof(results)
    if len(results) != 1:
        raise ValueError('index one source per receipt')
    result = results[0]
    source = Path(result['source']).resolve()
    roots = [(BASE / name).resolve() for name in ('native-classes', 'native-world', 'native-headers')]
    if not any(source.is_relative_to(root) for root in roots):
        raise ValueError('receipt source must be a native source or header')
    output = Path(output).resolve()
    if output.parent != (ROOT / 'work/2008-06/shared-layouts').resolve() or output.suffix.lower() != '.json':
        raise ValueError('receipt must be a JSON file in shared-layouts')
    receipt = receipts[str(source).casefold()]
    if receipt.get('status') != 'complete':
        raise ValueError('recorded build was not complete')
    if Path(receipt['object']).resolve() != Path(result['object']).resolve():
        raise ValueError('recorded object differs')
    checks = result['checks']
    if len({row['addr'] for row in checks}) != len(checks):
        raise ValueError('duplicate original address')

    def verify_inputs():
        expected = dict(receipt['dependencies'])
        expected[str(source)] = receipt['source_sha256']
        expected[receipt['object']] = receipt['object_sha256']
        changed = [name for name, digest in expected.items() if not Path(name).is_file() or sha(name) != digest]
        changed.extend(build_changes(receipt, tc))
        if changed:
            raise ValueError('proof inputs changed: ' + ', '.join(changed[:5]))
        require_proof(results)

    verify_inputs()
    rows = [{'address': row['addr'], 'symbol': row['symbol'], 'exact': True,
             'metrics': row['metrics'], 'data_matches': row['data_matches'],
             'verified_calls': row['call_identity']['calls'],
             'verified_references': row['reference_identity']['references']} for row in checks]
    data = {'source_path': str(source), 'source_sha256': receipt['source_sha256'],
            'object_sha256': receipt['object_sha256'], 'analysis': str(Path(analysis_path).resolve()),
            'checks': rows,
            'scope': 'Local masked byte/data, reviewed call and absolute-reference checks; original owner, provider selection, ABI, runtime and server credit remain separate.'}
    with output.open('x', encoding='utf-8') as handle:
        json.dump(data, handle, indent=2)
        handle.write('\n')
    try:
        verify_inputs()
    except BaseException:
        output.unlink()
        raise


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('action', choices=('start', 'run', 'status', 'analyze', '_worker'))
    parser.add_argument('input', type=Path, help='manifest for start/run; run directory otherwise')
    parser.add_argument('--manifest', type=Path, help='analyze: replacement comparisons against existing objects')
    parser.add_argument('--workers', type=int, choices=range(1, 9), default=3)
    parser.add_argument('--require-proof', action='store_true', help='run/analyze: fail unless every explicit check has fresh exact bytes, data and reviewed call bindings')
    parser.add_argument('--index-output', type=Path, help='analyze: write one new inactive receipt after all proof checks pass')
    args = parser.parse_args()
    if args.require_proof and args.action not in ('run', 'analyze'):
        parser.error('--require-proof supports foreground run/analyze only')
    if args.index_output and args.action != 'analyze':
        parser.error('--index-output supports analyze only')
    if args.action in ('start', 'run'):
        manifest = json.loads(args.input.read_text(encoding='utf-8-sig'))
        build = compiler_build(manifest)
        variant = compiler_variant(manifest)
        jobs = jobs_from(manifest)
        RUNS.mkdir(parents=True, exist_ok=True)
        run = RUNS / (time.strftime('%Y%m%d-%H%M%S') + '-' + uuid.uuid4().hex[:8])
        run.mkdir()
        save(run / 'manifest.json', {'compiler_build': build, 'compiler_variant': variant, 'jobs': jobs})
        save(run / 'summary.json', {'state': 'queued', 'run': str(run), 'total_sources': len(jobs)})
        if args.action == 'start':
            try:
                with (run / 'worker.log').open('w') as log:
                    options = {'creationflags': subprocess.CREATE_NO_WINDOW | subprocess.CREATE_NEW_PROCESS_GROUP} if os.name == 'nt' else {'start_new_session': True}
                    child = subprocess.Popen([sys.executable, str(Path(__file__).resolve()), '_worker', str(run), '--workers', str(args.workers)], cwd=ROOT,
                                             stdin=subprocess.DEVNULL, stdout=log, stderr=subprocess.STDOUT, close_fds=True, **options)
            except OSError as error:
                save(run / 'summary.json', {'state': 'failed', 'run': str(run), 'error': str(error)})
                raise
            save(run / 'launcher.json', {'pid': child.pid})
        else:
            execute(run, args.workers)
        summary = display(run)
    elif args.action == 'analyze':
        run = args.input.resolve()
        jobs = jobs_from(json.loads((args.manifest or run / 'manifest.json').read_text(encoding='utf-8-sig')))
        receipts = {r['source'].casefold(): r for r in json.loads((run / 'results.json').read_text())}
        results = []
        recorded = json.loads((run / 'manifest.json').read_text(encoding='utf-8-sig'))
        tc = selected_toolchain(recorded)
        for job in jobs:
            receipt = receipts[job['source'].casefold()]
            obj = Path(receipt['object'])
            if receipt['status'] != 'complete' or sha(obj) != receipt['object_sha256']:
                raise ValueError('recorded object failed or changed: ' + str(obj))
            changed = [p for p, digest in receipt['dependencies'].items() if not Path(p).exists() or sha(p) != digest]
            changed += build_changes(receipt, tc)
            results.append({'source': job['source'], 'object': str(obj), 'changed_inputs': changed,
                            'scope': 'recorded object analysis only; not a fresh build', **analyze_object(job, obj)})
            native_work.log_checks(run, job, results[-1], mode='analyze')
        # Analysis can take seconds. Inputs must still match after the whole batch.
        for result in results:
            receipt = receipts[result['source'].casefold()]
            expected = dict(receipt['dependencies'])
            expected[receipt['object']] = receipt['object_sha256']
            result['changed_inputs'] = sorted(set(result['changed_inputs']) | set(build_changes(receipt, tc)) | {
                p for p, digest in expected.items() if not Path(p).exists() or sha(p) != digest})
        output = run / ('analysis-' + uuid.uuid4().hex[:8] + '.json')
        save(output, results)
        print(json.dumps({'state': 'analyzed', 'sources': len(results), 'changed_input_sources': sum(bool(r['changed_inputs']) for r in results), 'results': str(output)}))
        if args.require_proof or args.index_output:
            require_proof(results)
        if args.index_output:
            index_inactive(results, receipts, tc, args.index_output, output)
            print(json.dumps({'state': 'indexed', 'receipt': str(args.index_output.resolve())}))
        return
    elif args.action == '_worker':
        execute(args.input.resolve(), args.workers)
        return
    else:
        summary = display(args.input.resolve())
    if summary['state'] == 'failed':
        raise SystemExit(1)
    if args.require_proof:
        require_proof(json.loads((Path(summary['run']) / 'results.json').read_text()))


def require_proof(results):
    checks = [row for result in results for row in result.get('checks', [])]
    for row in checks:
        for evidence in ('call_identity', 'reference_identity'):
            for name, digest in row.get(evidence, {}).get('import_evidence_inputs', {}).items():
                try:
                    if sha(Path(name)) != digest:
                        raise SystemExit('import proof input changed: ' + name)
                except OSError:
                    raise SystemExit('import proof input unavailable: ' + name)
    if (not checks or any(result.get('status', 'complete') != 'complete' or result.get('changed_inputs') for result in results)
            or any(row['status'] != 'exact' or 'data_errors' not in row or row['data_errors']
                   or not row.get('call_identity', {}).get('passed', False)
                   or not row.get('reference_identity', {}).get('passed', False) for row in checks)):
        raise SystemExit('proof incomplete; inspect saved receipt (no ABI/runtime/server credit)')


if __name__ == '__main__':
    main()

roc/integration_site.py.base:
"""docs/integration.json: native integration progress for the website (2008-06 rbxgs rebuild).
Same four groups as the Discord digest: integrated (linked rebuild reproduces it), exact waiting (mined 100%,
not yet integrated), partial, unmined. Per-function data is published on gh-pages only (see server.publish_pages)."""
import hashlib
import json
import posixpath
from pathlib import Path
import re
import sqlite3
import subprocess
from datetime import datetime, timezone
from zoneinfo import ZoneInfo

from roc.integration import CLIENT, ROOT, atomic_json

def readable(symbol):
    """MSVC decorated name -> Namespace::Class::method (enough for labels; full name stays in 'symbol')."""
    m = re.match(r"\?\?([01])([A-Za-z_]\w*)@((?:[A-Za-z_]\w*@)*)@", symbol)
    if m:
        scope = [m[2]] + [p for p in m[3].split("@") if p]
        cls = "::".join(reversed(scope))
        return "%s::%s%s" % (cls, "~" if m[1] == "1" else "", m[2])
    m = re.match(r"\?([A-Za-z_]\w*)@((?:[A-Za-z_]\w*@)+)@", symbol)
    if m:
        return "::".join(list(reversed([p for p in m[2].split("@") if p])) + [m[1]])
    return symbol


def owned_inventory(root, extra_reports=()):
    """Unique compiled owners, including explicitly published unaccepted candidates."""
    rows = {}
    paths = sorted((root / 'rebuild' / CLIENT / 'out').glob('*/report.json'))
    paths += [root / 'work/integration/owned-candidates.json',
              root / 'local/findings/2008-06/verification/owned-candidates.json']
    paths += list(extra_reports)
    for path in paths:
        if not path.exists():
            continue
        data = json.loads(path.read_text(encoding='utf-8'))
        for report in data.get('reports', [data]):
            module = report.get('module', path.parent.name)
            if module.casefold() == 'codegenanalogs':
                continue
            for address in report.get('owned_addrs', []):
                if re.fullmatch('[0-9a-f]{8}', address):
                    rows.setdefault(address, {'module': module})
    return rows


def linked_native_inventory(root):
    addresses = set()
    for path in sorted((root / 'rebuild' / CLIENT / 'out').glob('*/report.json')):
        report = json.loads(path.read_text(encoding='utf-8'))
        if report.get('linked') is not True or report.get('test_exit') != 0:
            continue
        addresses.update(address.lower() for address in report.get('owned_addrs', ())
                         if re.fullmatch('[0-9a-fA-F]{8}', address))
    return addresses


def coverage(root, scores, native, owned=None):
    """Website and webhook share the same code-only function/byte denominator."""
    owned = owned_inventory(root) if owned is None else owned
    groups = {key: {"functions": 0, "bytes": 0} for key in ("integrated", "owned_waiting", "exact_waiting", "partial", "unmined")}
    functions = {}
    for line in (root / "work" / CLIENT / "functions.jsonl").read_text().splitlines():
        if not line.strip():
            continue
        f = json.loads(line)
        if f.get("kind", "code") != "code":
            continue
        functions[f["addr"]] = f
        score = scores.get(f["addr"], 0)
        key = "integrated" if f["addr"] in native else "owned_waiting" if f["addr"] in owned else "exact_waiting" if score == 100 else "partial" if score else "unmined"
        groups[key]["functions"] += 1
        groups[key]["bytes"] += f["size"]
    return groups, functions


def inactive_code(root):
    """addr -> [symbol, exact, receipt] from inactive native trial receipts (code exists, not integrated)."""
    found = {}
    def walk(node, name, stamp):
        if isinstance(node, dict):
            addr = node.get("address") or node.get("original_address")
            symbol = node.get("symbol") or node.get("source_symbol")
            exact = node.get("relocation_normalized_exact", node.get("exact"))
            if isinstance(addr, str) and isinstance(symbol, str) and isinstance(exact, bool):
                exact = exact and receipt_valid
                addr = addr.lower().removeprefix("0x").zfill(8)
                old = found.get(addr)
                # exact beats not-exact; otherwise the newest receipt wins
                if not old or (exact, stamp) > (old[1], old[3]):
                    found[addr] = [symbol, exact, name, stamp, receipt_source]
            for value in node.values():
                walk(value, name, stamp)
        elif isinstance(node, list):
            for value in node:
                walk(value, name, stamp)
    # native source of a trial receipt: the repo file whose hash it records, else the first existing .cpp it names
    by_hash = {}
    for item in (sorted((root / "rebuild" / CLIENT / "native-classes").rglob("*.cpp")) +
                 sorted((root / "rebuild" / CLIENT / "native-world").rglob("*.cpp")) +
                 sorted((root / "rebuild" / CLIENT / "native-headers").rglob("*.h"))):
        by_hash.setdefault(hashlib.sha256(item.read_bytes()).hexdigest(), str(item))
    def source_in(text, data):
        digest = data.get("source_sha256") if isinstance(data, dict) else None
        named = data.get("source_path") if isinstance(data, dict) else None
        if isinstance(named, str) and isinstance(digest, str):
            item = (root / named).resolve()
            if item.is_relative_to(root.resolve()) and item.is_file() and hashlib.sha256(item.read_bytes()).hexdigest() == digest:
                return str(item)
        if isinstance(digest, str):
            return by_hash.get(digest)
        for named in re.findall(r'"([^"\n]*?\.cpp)"', text):
            item = Path(named.replace("\\\\", "/"))
            item = item if item.is_absolute() else root / item
            if item.is_file():
                return str(item)
        return None
    receipt_source = None
    receipt_valid = True
    for path in (root / "work" / CLIENT / "shared-layouts").glob("*.json"):
        try:
            text = path.read_text(encoding="utf-8")
            data = json.loads(text)
            receipt_source = source_in(text, data)
            receipt_valid = not isinstance(data, dict) or not isinstance(data.get("source_sha256"), str) or receipt_source is not None
            walk(data, path.name, path.stat().st_mtime)
            # single-function trial receipt with no exact verdict: native code exists, unproven
            if isinstance(data, dict) and isinstance(data.get("address"), str) and (
                    "inputs" in data or "source_sha256" in data):
                found.setdefault(data["address"].lower().removeprefix("0x").zfill(8),
                                 [path.stem, False, path.name, 0, receipt_source])
        except (ValueError, OSError):
            continue
    # native_bulk proofs (work/native-client/prove.py: full census + per-file runs). Byte-exact rows are inactive
    # (exact); a byte-matched body at one candidate still waiting for identity/reference proof is draft.
    manifests = sorted((root / "work/native-client/prove-out").glob("*/manifest.json"), key=lambda p: p.stat().st_mtime)
    # Collect the latest single-source mapping while processing each manifest once.
    single, bulk = {}, set()
    for path in manifests:
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except (ValueError, OSError):
            continue
        stamp = path.stat().st_mtime
        for family in data.get("families", []):
            if len(family.get("jobs", [])) == 1:
                try:
                    for row in family.get("symbols", []):
                        single[row["symbol"]] = family["jobs"][0]["source"]
                except KeyError:
                    pass
            source_of = {(c["addr"], c["symbol"]): job["source"] for job in family.get("jobs", []) for c in job.get("checks", [])}
            for row in family.get("symbols", []):
                exact = row.get("status") == "inactive_exact"
                candidates = row.get("candidates") or []
                if not candidates or row["symbol"].startswith(("__", "$")) or (not exact and len(candidates) != 1):
                    continue
                for addr in candidates:
                    old = found.get(addr)
                    if not old or (exact, stamp) > (old[1], old[3]):
                        found[addr] = [row["symbol"], exact, "native-bulk:" + path.parent.name, stamp,
                                       source_of.get((addr, row["symbol"]))]
                        bulk.add(addr)
    for addr in bulk:
        if not found[addr][4]:
            found[addr][4] = single.get(found[addr][0])
    # native source with an address-named method but no receipt yet (e.g. CRobloxDoc::handle_453c30)
    for path in sorted((root / "rebuild" / CLIENT).glob("*/*.cpp")):
        text = path.read_text(encoding="utf-8", errors="replace")
        for cls, addr in re.findall(r"\b(\w+)::handle_([0-9a-f]{6,8})\b", text):
            found.setdefault(addr.zfill(8), ["%s::handle_%s" % (cls, addr), False, path.relative_to(root).as_posix(), 0, str(path)])
    texts = {}

    def located(symbol, source):
        """[repo-relative path, line of the definition (1 if not found)] of the native source, or None."""
        if not source:
            return None
        path = Path(source)
        try:
            rel = path.resolve().relative_to(root.resolve()).as_posix()
        except ValueError:
            return None
        if path not in texts:
            texts[path] = path.read_text(encoding="utf-8", errors="replace").splitlines() if path.is_file() else []
        parts = readable(symbol).split("(")[0].split("::")
        needle = "::".join(parts[-2:]) + "("
        line = next((i + 1 for i, text in enumerate(texts[path]) if needle in text.replace(" (", "(")), 1)
        if line == 1 and path.suffix == ".h":
            line = next((i + 1 for i, text in enumerate(texts[path])
                         if re.search(r"\b" + re.escape(parts[-1]) + r"\s*\(", text)), 1)
        return [rel, line]
    # addr -> [readable symbol, exact, receipt, [native source path, line] or None]
    return {a: [readable(v[0]) if v[0].startswith("?") else v[0]] + v[1:3] + [located(v[0], v[4] if len(v) > 4 else None)]
            for a, v in sorted(found.items())}


WORK = "refs/remotes/origin/work"
WRAPPER = re.compile(r'^\s*(?://[^\n]*\n\s*)*#include "([^"]+\.(?:cpp|c))"\s*$')


def work_blobs(root, paths):
    """{path: text} for workspace paths on the published work branch (one git cat-file call)."""
    paths = sorted(set(paths))
    if not paths:
        return {}
    run = subprocess.run(["git", "cat-file", "--batch"], cwd=root, capture_output=True,
                         input="".join("%s:%s\n" % (WORK, p) for p in paths).encode())
    out, data, at = {}, run.stdout, 0
    for path in paths:
        end = data.index(b"\n", at)
        header = data[at:end].split()
        at = end + 1
        if len(header) == 3 and header[1] == b"blob":
            size = int(header[2])
            out[path] = data[at:at + size].decode("utf-8", errors="replace")
            at += size + 1
    return out


def function_line(text, name):
    parts = name.split("(")[0].split("::")
    needle = "::".join(parts[-2:]) + "("
    return next((i + 1 for i, line in enumerate(text.splitlines()) if needle in line.replace(" (", "(")), 1)


def follow_wrappers(root, links, names):
    """Compatibility units on the work branch (`#include "../WindowsClient/src/X.cpp"`) link their real file."""
    for _ in range(3):  # wrappers of wrappers
        texts = work_blobs(root, [l["path"] for l in links.values()])
        targets = {}
        for path, text in texts.items():
            hit = WRAPPER.match(text) if len(text) < 2000 else None
            if hit:
                targets[path] = posixpath.normpath(posixpath.join(posixpath.dirname(path), hit.group(1)))
        if not targets:
            break
        real = work_blobs(root, targets.values())
        for addr, link in links.items():
            target = targets.get(link["path"])
            if target in real:
                link["path"], link["line"] = target, function_line(real[target], names.get(addr, ""))


def integrated_sources(root, missing, published):
    """{addr: link} for integrated functions: owning object in a linked module -> the source that built it.
    Roblox/OpenRBX trees link to their public repositories at the pinned revision; native layers and repo sources
    link to the work branch. Upstream library trees and mined swaps (already linked) are skipped."""
    from roc import libs, rebuild
    lock = json.loads((root / "research/native-source-lock.json").read_text())
    repos = {"tools/rbxgs/": "https://github.com/RBLXDecomp/RBXGSdecomp/blob/%s/" % lock.get("https://github.com/RBLXDecomp/RBXGSdecomp.git", "master"),
             "tools/openrbx/": "https://github.com/Asphaltian/OpenRBX/blob/%s/" % lock.get("https://github.com/Asphaltian/OpenRBX.git", "main"),
             "work/upstream/OpenRBX/": "https://github.com/Asphaltian/OpenRBX/blob/%s/" % lock.get("https://github.com/Asphaltian/OpenRBX.git", "main")}
    out, texts = {}, {}
    for _, spec in rebuild.live_module_specs(CLIENT):
        folder = root / "rebuild" / CLIENT / "out" / spec["name"]
        owners = folder / "owned-symbols.json"
        report = folder / "report.json"
        if not owners.exists() or not report.exists():
            continue
        choices = json.loads(report.read_text()).get("choices") or {}
        sources = {}
        for layer in spec["layers"]:
            try:
                if layer["mode"] == "recipe":
                    src = libs._case_path(libs.LIBS / libs.RECIPES[layer["recipe"]]["src"])
                    listed = libs.RECIPES[layer["recipe"]].get("files")
                    globs = [] if layer["files"] == "recipe" and isinstance(listed, list) else \
                        (listed if layer["files"] == "recipe" else layer["files"]).split()
                    paths = [src / f for f in listed] if not globs else [p for g in globs for p in src.glob(g)]
                else:
                    paths = [p for g in layer["files"].split() for p in (root / layer["dir"]).glob(g)]
            except (KeyError, OSError):
                continue
            sources["layer-" + layer["name"]] = {p.stem.lower(): p for p in paths}
        for addr, rows in json.loads(owners.read_text()).items():
            if addr not in missing or addr in out:
                continue
            for row in rows:
                obj = row["object"]
                path = sources.get(choices.get(obj) or "", {}).get(Path(obj).stem.lower())
                if path is None:
                    continue
                try:
                    rel = path.resolve().relative_to(root.resolve()).as_posix()
                except ValueError:
                    continue
                name = readable(row["symbol"]) if row["symbol"].startswith("?") else row["symbol"]
                prefix = next((p for p in repos if rel.startswith(p)), None)
                if prefix:
                    if path not in texts:
                        texts[path] = path.read_text(encoding="utf-8", errors="replace")
                    out[addr] = {"url": repos[prefix] + rel[len(prefix):], "line": function_line(texts[path], name)}
                elif rel in published:
                    if path not in texts:
                        texts[path] = path.read_text(encoding="utf-8", errors="replace")
                    out[addr] = {"path": "workspace/" + rel, "line": function_line(texts[path], name)}
                if addr in out:
                    break
    return out


def link_errors(root):
    """Unresolved-symbol families from linked trial receipts (*blocker-ranking.json): family -> errors."""
    out = {"trials": [], "families": {}}
    for path in sorted((root / "work" / CLIENT / "shared-layouts").glob("*blocker-ranking*.json")):
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except (ValueError, OSError):
            continue
        out["trials"].append({"receipt": path.name, "link_exit": data.get("link_exit"),
                              "error_lines": data.get("error_lines"), "revision": str(data.get("receipt_revision", ""))[:10]})
        for row in data.get("ranked", []):
            entry = out["families"].setdefault(row["family"], {"symbols": [], "objects": [], "receipts": []})
            entry["symbols"] = sorted(set(entry["symbols"]) | {s["name"] for s in row.get("symbols", [])})
            entry["objects"] = sorted(set(entry["objects"]) | set(row.get("objects", [])))
            entry["receipts"].append(path.name)
    return out


def commit(root):
    head = root / ".git" / "HEAD"
    try:
        ref = head.read_text().strip()
        return (root / ".git" / ref[5:]).read_text().strip()[:10] if ref.startswith("ref: ") else ref[:10]
    except OSError:
        return ""


def announce_inactive(before, after, log=print):
    """Integration Digest (report only) for addresses that newly became inactive (exact) or draft native code."""
    rows = [(a, v) for a, v in after.items() if a not in before or (v[1] and not before[a][1])]
    if not rows:
        return
    from roc.integration_notify import post_section
    from roc.reports import inline_code
    rows.sort(key=lambda r: (not r[1][1], r[0]))
    lines = ["%s `%s` %s" % ("🟣 inactive" if v[1] else "🩷 draft", a, inline_code(v[0])) for a, v in rows[:12]]
    if len(rows) > 12:
        lines.append("+%d more" % (len(rows) - 12))
    section = {"name": "🟪 New Native Code · inactive (exact) / draft, not integrated",
               "value": "\n".join(lines)[:1024], "inline": False}
    post_section(None, "site", "rebuild", section, background=False)
    log("Integration digest: %d newly inactive/draft" % len(rows))


def build(root=ROOT, log=print, output=None, extra_reports=()):
    out = root / "rebuild" / CLIENT / "out"
    native_path = root / "work/integration/progress-native.json"
    server_native = set(json.loads(native_path.read_text())["addresses"]) if native_path.exists() else set()
    # Isolated linked module reports do not prove selection in the client.
    native = server_native
    names_path = out / "native-names.json"
    names = json.loads(names_path.read_text()) if names_path.exists() else {}
    db = sqlite3.connect("file:%s?mode=ro" % (root / "work/server.db").as_posix(), uri=True, timeout=30)
    try:
        scores = dict(db.execute("SELECT addr,score FROM funcs WHERE client=?", (CLIENT,)).fetchall())
        jobs = db.execute("SELECT id,user,model,unit,receipt,updated FROM integration_jobs WHERE state='accepted' "
                          "ORDER BY updated DESC").fetchall()
        leaders = db.execute("SELECT user,model,COUNT(*) FROM integration_credit WHERE client=? GROUP BY user,model "
                             "ORDER BY COUNT(*) DESC", (CLIENT,)).fetchall()
        # agent (Codex/Claude/...) claims: latest per unit; unexpired ones are live work
        now = datetime.now(timezone.utc).timestamp()
        activity, working = {}, {}
        for unit, user, worker, expires, state, addresses in db.execute(
                "SELECT unit,user,worker,expires,state,addresses FROM integration_claims WHERE client=? ORDER BY rowid",
                (CLIENT,)):
            live = expires > now and state == "claimed"
            activity[unit] = ["working" if live else state, user, worker]
            if live:
                for addr in json.loads(addresses or "[]"):
                    working[str(addr).lower().removeprefix("0x").zfill(8)] = [user, worker, unit]
    finally:
        db.close()
    # site's middle bucket: inactive (receipt-exact) or draft native code, not yet integrated
    inactive = inactive_code(root)
    owned = set(inactive)
    groups, functions = coverage(root, scores, native, owned)
    units = {job: unit for job, _, _, unit, _, _ in jobs}
    receipts = []
    daily = {}
    seen = set()
    for job, user, model, unit, receipt, updated in jobs:
        r = json.loads(receipt or "{}")
        key = r.get("job", job)
        if key in seen:
            continue
        seen.add(key)
        day = datetime.fromtimestamp(updated, ZoneInfo("America/New_York")).strftime("%Y-%m-%d")
        row = daily.setdefault(day, {"day": day, "gains": 0, "jobs": 0, "models": {}})
        gains = len(r.get("new_distinct", r.get("gains", [])))
        row["gains"] += gains
        row["jobs"] += 1
        series = row["models"].setdefault(model or "Unknown", {"gains": 0, "jobs": 0})
        series["gains"] += gains
        series["jobs"] += 1
        unit = ", ".join(dict.fromkeys(units.get(j, "") for j in r.get("merged_jobs", [job])))
        receipts.append({"job": key[:8], "user": user, "model": model, "units": unit[:120],
                         "gains": len(r.get("gains", [])), "distinct_gains": len(r.get("new_distinct", r.get("gains", []))), "owned_after": r.get("owned_after"),
                         "when": datetime.fromtimestamp(updated, timezone.utc).strftime("%Y-%m-%d %H:%M UTC")})
    shown = {a: names[a] for a in names if a in native or (names[a].get("score") or 0) >= 50}
    links_path = root / 'local/findings/2008-06/verification/native-source-links.json'
    sources = json.loads(links_path.read_text(encoding='utf-8')) if links_path.exists() else {}
    data = {"client": CLIENT, "updated": datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC"),
            "groups": groups,
            "commit": commit(root),
            "link_errors": link_errors(root),
            # unit -> [latest claim state ("working", "released", "parked: reason", ...), user, worker]
            "activity": activity,
            # addr -> [user, worker, unit] for unexpired agent claims
            "working": working,
            "native": sorted(native),
            "server_native": sorted(server_native),
            "owned": sorted(set(owned) & functions.keys()),
            "owned_waiting": sorted((set(owned) & functions.keys()) - native),
            "ownership_note": "Inactive / draft: native code exists (receipt-exact or draft) but is not integrated; link, runtime and server acceptance still pending.",
            # inactive native code: addr -> [decorated symbol, receipt-proven exact, receipt file]
            "inactive": {a: v for a, v in inactive.items() if a not in native},
            "sources": {a: value for a, value in sources.items() if a in native},
            # addr -> [readable name, decorated symbol, rebuilt score (100 = integrated)]
            "names": {a: [readable(v["symbol"]), v["symbol"], 100 if a in native else v.get("score")] for a, v in sorted(shown.items())},
            "daily": [daily[day] for day in sorted(daily)],
            "jobs": receipts[:100],
            "leaderboard": [{"user": u, "model": m, "native_credits": n} for u, m, n in leaders]}
    # addr -> {path, line} on the published work branch (site links these beside the mined source)
    listed = subprocess.run(["git", "ls-tree", "-r", "--name-only", "refs/remotes/origin/work", "--", "workspace/"],
                            cwd=root, capture_output=True, text=True).stdout.splitlines()
    published = {path.removeprefix("workspace/") for path in listed if path}
    data["inactive_sources"] = {a: {"path": "workspace/" + v[3][0], "line": v[3][1]}
                                for a, v in data["inactive"].items() if len(v) > 3 and v[3] and v[3][0] in published}
    follow_wrappers(root, data["inactive_sources"], {a: v[0] for a, v in data["inactive"].items()})
    # integrated functions without an indexed source: the object that owns them in the linked rebuild -> its source
    for addr, link in integrated_sources(root, native - set(data["sources"]), published).items():
        data["sources"][addr] = link
    follow_wrappers(root, {a: s for a, s in data["sources"].items() if "url" not in s},
                    {a: v[0] for a, v in data["names"].items()})
    for key, exact in (("native_inactive", True), ("native_draft", False)):
        hits = [functions[a] for a, v in data["inactive"].items() if v[1] == exact and a in functions]
        # separate from "groups": groups partition the code and are summed by the site
        data.setdefault("native_code", {})[key[7:]] = {"functions": len(hits), "bytes": sum(f["size"] for f in hits)}
    path = output or root / "docs/integration.json"
    previous_path = path if path.exists() else root / "docs/integration.json"
    previous = json.loads(previous_path.read_text(encoding="utf-8")) if previous_path.exists() else {}
    history = {row["day"]: row for row in previous.get("history", [])} if previous.get("client") == CLIENT else {}
    published_path = root / "docs/integration.json"
    if published_path != previous_path and published_path.exists():
        published = json.loads(published_path.read_text(encoding="utf-8"))
        if published.get("client") == CLIENT:
            history.update({row["day"]: row for row in published.get("history", [])})
    day = datetime.now(ZoneInfo("America/New_York")).strftime("%Y-%m-%d")
    history[day] = {"day": day, "groups": data["groups"], "native_code": data.get("native_code", {})}
    data["history"] = [history[day] for day in sorted(history)]
    atomic_json(path, data)
    if output is None and "inactive" in previous:  # first build has no baseline: don't announce everything
        announce_inactive(previous["inactive"], data["inactive"], log)
    log("Integration site data: %d integrated, %d named" % (len(native), len(data["names"])))
    return data


if __name__ == "__main__":
    build()

roc/integration_site.py.text:
"""docs/integration.json: native integration progress for the website (2008-06 rbxgs rebuild).
Same four groups as the Discord digest: integrated (linked rebuild reproduces it), exact waiting (mined 100%,
not yet integrated), partial, unmined. Per-function data is published on gh-pages only (see server.publish_pages)."""
import hashlib
import json
import posixpath
from pathlib import Path
import re
import sqlite3
import subprocess
from datetime import datetime, timezone
from zoneinfo import ZoneInfo

from roc.integration import CLIENT, ROOT, atomic_json

def readable(symbol):
    """MSVC decorated name -> Namespace::Class::method (enough for labels; full name stays in 'symbol')."""
    m = re.match(r"\?\?([01])([A-Za-z_]\w*)@((?:[A-Za-z_]\w*@)*)@", symbol)
    if m:
        scope = [m[2]] + [p for p in m[3].split("@") if p]
        cls = "::".join(reversed(scope))
        return "%s::%s%s" % (cls, "~" if m[1] == "1" else "", m[2])
    m = re.match(r"\?([A-Za-z_]\w*)@((?:[A-Za-z_]\w*@)+)@", symbol)
    if m:
        return "::".join(list(reversed([p for p in m[2].split("@") if p])) + [m[1]])
    return symbol


def owned_inventory(root, extra_reports=()):
    """Unique compiled owners, including explicitly published unaccepted candidates."""
    rows = {}
    paths = sorted((root / 'rebuild' / CLIENT / 'out').glob('*/report.json'))
    paths += [root / 'work/integration/owned-candidates.json',
              root / 'local/findings/2008-06/verification/owned-candidates.json']
    paths += list(extra_reports)
    for path in paths:
        if not path.exists():
            continue
        data = json.loads(path.read_text(encoding='utf-8'))
        for report in data.get('reports', [data]):
            module = report.get('module', path.parent.name)
            if module.casefold() == 'codegenanalogs':
                continue
            for address in report.get('owned_addrs', []):
                if re.fullmatch('[0-9a-f]{8}', address):
                    rows.setdefault(address, {'module': module})
    return rows


def linked_native_inventory(root):
    addresses = set()
    for path in sorted((root / 'rebuild' / CLIENT / 'out').glob('*/report.json')):
        report = json.loads(path.read_text(encoding='utf-8'))
        if report.get('linked') is not True or report.get('test_exit') != 0:
            continue
        addresses.update(address.lower() for address in report.get('owned_addrs', ())
                         if re.fullmatch('[0-9a-fA-F]{8}', address))
    return addresses


def coverage(root, scores, native, owned=None):
    """Website and webhook share the same code-only function/byte denominator."""
    owned = owned_inventory(root) if owned is None else owned
    groups = {key: {"functions": 0, "bytes": 0} for key in ("integrated", "owned_waiting", "exact_waiting", "partial", "unmined")}
    functions = {}
    for line in (root / "work" / CLIENT / "functions.jsonl").read_text().splitlines():
        if not line.strip():
            continue
        f = json.loads(line)
        if f.get("kind", "code") != "code":
            continue
        functions[f["addr"]] = f
        score = scores.get(f["addr"], 0)
        key = "integrated" if f["addr"] in native else "owned_waiting" if f["addr"] in owned else "exact_waiting" if score == 100 else "partial" if score else "unmined"
        groups[key]["functions"] += 1
        groups[key]["bytes"] += f["size"]
    return groups, functions


def bulk_manifest(path, cache_dir):
    """Cache the small fields needed by the site; changed manifests are reread."""
    stat = path.stat()
    fingerprint = [stat.st_size, stat.st_mtime_ns, stat.st_ctime_ns]
    key = hashlib.sha256(str(path.resolve()).encode()).hexdigest()[:24]
    cached = cache_dir / (key + ".json")
    try:
        value = json.loads(cached.read_text(encoding="utf-8"))
        current = path.stat()
        if (value.get("version") == 1 and value.get("fingerprint") == fingerprint and
                fingerprint == [current.st_size, current.st_mtime_ns, current.st_ctime_ns] and
                isinstance(value.get("families"), list)):
            return value["families"]
    except (OSError, ValueError, KeyError, AttributeError):
        pass
    data = json.loads(path.read_text(encoding="utf-8"))
    families = []
    for family in data.get("families", []):
        jobs = [{"source": job["source"], "checks": [
            {"addr": check["addr"], "symbol": check["symbol"]}
            for check in job.get("checks", [])]} for job in family.get("jobs", [])]
        symbols = [{"symbol": row["symbol"], "status": row.get("status"),
                    "candidates": row.get("candidates")} for row in family.get("symbols", [])]
        families.append({"jobs": jobs, "symbols": symbols})
    after = path.stat()
    if fingerprint != [after.st_size, after.st_mtime_ns, after.st_ctime_ns]:
        raise OSError("manifest changed while reading")
    try:
        atomic_json(cached, {"version": 1, "fingerprint": fingerprint, "families": families})
    except OSError:
        pass  # Cache is optional; a read-only workspace can still refresh.
    return families


def inactive_code(root):
    """addr -> [symbol, exact, receipt] from inactive native trial receipts (code exists, not integrated)."""
    found = {}
    review_path = root / 'docs/native-reference-review.json'
    if review_path.exists():
        data = json.loads(review_path.read_text(encoding='utf-8'))
        if (not isinstance(data, dict) or not isinstance(data.get('addresses'), list)
                or any(not isinstance(a, str) or not re.fullmatch(r'(?:0x)?[0-9a-fA-F]{8}', a)
                       for a in data['addresses'])):
            raise ValueError('invalid native reference review list')
        review = {str(a).lower().removeprefix('0x').zfill(8) for a in data['addresses']}
    else:
        review = set()
    def walk(node, name, stamp):
        if isinstance(node, dict):
            addr = node.get("address") or node.get("original_address")
            symbol = node.get("symbol") or node.get("source_symbol")
            exact = node.get("relocation_normalized_exact", node.get("exact"))
            if isinstance(addr, str) and isinstance(symbol, str) and isinstance(exact, bool):
                exact = exact and receipt_valid
                addr = addr.lower().removeprefix("0x").zfill(8)
                if addr in review:
                    refs, calls = node.get('verified_references'), node.get('verified_calls')
                    exact = bool(exact and isinstance(refs, list) and isinstance(calls, list)
                                 and all(r.get('status', '').startswith('verified_') for r in refs + calls))
                old = found.get(addr)
                # exact beats not-exact; otherwise the newest receipt wins
                if not old or (exact, stamp) > (old[1], old[3]):
                    found[addr] = [symbol, exact, name, stamp, receipt_source]
            for value in node.values():
                walk(value, name, stamp)
        elif isinstance(node, list):
            for value in node:
                walk(value, name, stamp)
    # native source of a trial receipt: the repo file whose hash it records, else the first existing .cpp it names
    by_hash = {}
    for item in (sorted((root / "rebuild" / CLIENT / "native-classes").rglob("*.cpp")) +
                 sorted((root / "rebuild" / CLIENT / "native-world").rglob("*.cpp")) +
                 sorted((root / "rebuild" / CLIENT / "native-headers").rglob("*.h"))):
        by_hash.setdefault(hashlib.sha256(item.read_bytes()).hexdigest(), str(item))
    def source_in(text, data):
        digest = data.get("source_sha256") if isinstance(data, dict) else None
        named = data.get("source_path") if isinstance(data, dict) else None
        if isinstance(named, str) and isinstance(digest, str):
            item = (root / named).resolve()
            if item.is_relative_to(root.resolve()) and item.is_file() and hashlib.sha256(item.read_bytes()).hexdigest() == digest:
                return str(item)
        if isinstance(digest, str):
            return by_hash.get(digest)
        for named in re.findall(r'"([^"\n]*?\.cpp)"', text):
            item = Path(named.replace("\\\\", "/"))
            item = item if item.is_absolute() else root / item
            if item.is_file():
                return str(item)
        return None
    receipt_source = None
    receipt_valid = True
    for path in (root / "work" / CLIENT / "shared-layouts").glob("*.json"):
        try:
            text = path.read_text(encoding="utf-8")
            data = json.loads(text)
            receipt_source = source_in(text, data)
            receipt_valid = not isinstance(data, dict) or not isinstance(data.get("source_sha256"), str) or receipt_source is not None
            walk(data, path.name, path.stat().st_mtime)
            # single-function trial receipt with no exact verdict: native code exists, unproven
            if isinstance(data, dict) and isinstance(data.get("address"), str) and (
                    "inputs" in data or "source_sha256" in data):
                found.setdefault(data["address"].lower().removeprefix("0x").zfill(8),
                                 [path.stem, False, path.name, 0, receipt_source])
        except (ValueError, OSError):
            continue
    # native_bulk proofs (work/native-client/prove.py: full census + per-file runs). Byte-exact rows are inactive
    # (exact); a byte-matched body at one candidate still waiting for identity/reference proof is draft.
    manifests = sorted((root / "work/native-client/prove-out").glob("*/manifest.json"), key=lambda p: p.stat().st_mtime)
    # Collect the latest single-source mapping while processing each manifest once.
    single, bulk = {}, set()
    for path in manifests:
        try:
            families = bulk_manifest(path, root / "work/integration/inactive-bulk-cache")
        except (ValueError, OSError):
            continue
        stamp = path.stat().st_mtime
        for family in families:
            if len(family.get("jobs", [])) == 1:
                try:
                    for row in family.get("symbols", []):
                        single[row["symbol"]] = family["jobs"][0]["source"]
                except KeyError:
                    pass
            source_of = {(c["addr"], c["symbol"]): job["source"] for job in family.get("jobs", []) for c in job.get("checks", [])}
            for row in family.get("symbols", []):
                exact = row.get("status") == "inactive_exact"
                candidates = row.get("candidates") or []
                if not candidates or row["symbol"].startswith(("__", "$")) or (not exact and len(candidates) != 1):
                    continue
                for addr in candidates:
                    candidate_exact = exact and addr.lower().removeprefix('0x').zfill(8) not in review
                    old = found.get(addr)
                    if not old or (candidate_exact, stamp) > (old[1], old[3]):
                        found[addr] = [row["symbol"], candidate_exact, "native-bulk:" + path.parent.name, stamp,
                                       source_of.get((addr, row["symbol"]))]
                        bulk.add(addr)
    for addr in bulk:
        if not found[addr][4]:
            found[addr][4] = single.get(found[addr][0])
    # native source with an address-named method but no receipt yet (e.g. CRobloxDoc::handle_453c30)
    for path in sorted((root / "rebuild" / CLIENT).glob("*/*.cpp")):
        text = path.read_text(encoding="utf-8", errors="replace")
        for cls, addr in re.findall(r"\b(\w+)::handle_([0-9a-f]{6,8})\b", text):
            found.setdefault(addr.zfill(8), ["%s::handle_%s" % (cls, addr), False, path.relative_to(root).as_posix(), 0, str(path)])
    texts = {}

    def located(symbol, source):
        """[repo-relative path, line of the definition (1 if not found)] of the native source, or None."""
        if not source:
            return None
        path = Path(source)
        try:
            rel = path.resolve().relative_to(root.resolve()).as_posix()
        except ValueError:
            return None
        if path not in texts:
            texts[path] = path.read_text(encoding="utf-8", errors="replace").splitlines() if path.is_file() else []
        parts = readable(symbol).split("(")[0].split("::")
        needle = "::".join(parts[-2:]) + "("
        line = next((i + 1 for i, text in enumerate(texts[path]) if needle in text.replace(" (", "(")), 1)
        if line == 1 and path.suffix == ".h":
            line = next((i + 1 for i, text in enumerate(texts[path])
                         if re.search(r"\b" + re.escape(parts[-1]) + r"\s*\(", text)), 1)
        return [rel, line]
    # addr -> [readable symbol, exact, receipt, [native source path, line] or None]
    return {a: [readable(v[0]) if v[0].startswith("?") else v[0]] + v[1:3] + [located(v[0], v[4] if len(v) > 4 else None)]
            for a, v in sorted(found.items())}


WORK = "refs/remotes/origin/work"
WRAPPER = re.compile(r'^\s*(?://[^\n]*\n\s*)*#include "([^"]+\.(?:cpp|c))"\s*$')


def work_blobs(root, paths):
    """{path: text} for workspace paths on the published work branch (one git cat-file call)."""
    paths = sorted(set(paths))
    if not paths:
        return {}
    run = subprocess.run(["git", "cat-file", "--batch"], cwd=root, capture_output=True,
                         input="".join("%s:%s\n" % (WORK, p) for p in paths).encode())
    out, data, at = {}, run.stdout, 0
    for path in paths:
        end = data.index(b"\n", at)
        header = data[at:end].split()
        at = end + 1
        if len(header) == 3 and header[1] == b"blob":
            size = int(header[2])
            out[path] = data[at:at + size].decode("utf-8", errors="replace")
            at += size + 1
    return out


def function_line(text, name):
    parts = name.split("(")[0].split("::")
    needle = "::".join(parts[-2:]) + "("
    return next((i + 1 for i, line in enumerate(text.splitlines()) if needle in line.replace(" (", "(")), 1)


def follow_wrappers(root, links, names):
    """Compatibility units on the work branch (`#include "../WindowsClient/src/X.cpp"`) link their real file."""
    for _ in range(3):  # wrappers of wrappers
        texts = work_blobs(root, [l["path"] for l in links.values()])
        targets = {}
        for path, text in texts.items():
            hit = WRAPPER.match(text) if len(text) < 2000 else None
            if hit:
                targets[path] = posixpath.normpath(posixpath.join(posixpath.dirname(path), hit.group(1)))
        if not targets:
            break
        real = work_blobs(root, targets.values())
        for addr, link in links.items():
            target = targets.get(link["path"])
            if target in real:
                link["path"], link["line"] = target, function_line(real[target], names.get(addr, ""))


def integrated_sources(root, missing, published):
    """{addr: link} for integrated functions: owning object in a linked module -> the source that built it.
    Roblox/OpenRBX trees link to their public repositories at the pinned revision; native layers and repo sources
    link to the work branch. Upstream library trees and mined swaps (already linked) are skipped."""
    from roc import libs, rebuild
    lock = json.loads((root / "research/native-source-lock.json").read_text())
    repos = {"tools/rbxgs/": "https://github.com/RBLXDecomp/RBXGSdecomp/blob/%s/" % lock.get("https://github.com/RBLXDecomp/RBXGSdecomp.git", "master"),
             "tools/openrbx/": "https://github.com/Asphaltian/OpenRBX/blob/%s/" % lock.get("https://github.com/Asphaltian/OpenRBX.git", "main"),
             "work/upstream/OpenRBX/": "https://github.com/Asphaltian/OpenRBX/blob/%s/" % lock.get("https://github.com/Asphaltian/OpenRBX.git", "main")}
    out, texts = {}, {}
    for _, spec in rebuild.live_module_specs(CLIENT):
        folder = root / "rebuild" / CLIENT / "out" / spec["name"]
        owners = folder / "owned-symbols.json"
        report = folder / "report.json"
        if not owners.exists() or not report.exists():
            continue
        choices = json.loads(report.read_text()).get("choices") or {}
        sources = {}
        for layer in spec["layers"]:
            try:
                if layer["mode"] == "recipe":
                    src = libs._case_path(libs.LIBS / libs.RECIPES[layer["recipe"]]["src"])
                    listed = libs.RECIPES[layer["recipe"]].get("files")
                    globs = [] if layer["files"] == "recipe" and isinstance(listed, list) else \
                        (listed if layer["files"] == "recipe" else layer["files"]).split()
                    paths = [src / f for f in listed] if not globs else [p for g in globs for p in src.glob(g)]
                else:
                    paths = [p for g in layer["files"].split() for p in (root / layer["dir"]).glob(g)]
            except (KeyError, OSError):
                continue
            sources["layer-" + layer["name"]] = {p.stem.lower(): p for p in paths}
        for addr, rows in json.loads(owners.read_text()).items():
            if addr not in missing or addr in out:
                continue
            for row in rows:
                obj = row["object"]
                path = sources.get(choices.get(obj) or "", {}).get(Path(obj).stem.lower())
                if path is None:
                    continue
                try:
                    rel = path.resolve().relative_to(root.resolve()).as_posix()
                except ValueError:
                    continue
                name = readable(row["symbol"]) if row["symbol"].startswith("?") else row["symbol"]
                prefix = next((p for p in repos if rel.startswith(p)), None)
                if prefix:
                    if path not in texts:
                        texts[path] = path.read_text(encoding="utf-8", errors="replace")
                    out[addr] = {"url": repos[prefix] + rel[len(prefix):], "line": function_line(texts[path], name)}
                elif rel in published:
                    if path not in texts:
                        texts[path] = path.read_text(encoding="utf-8", errors="replace")
                    out[addr] = {"path": "workspace/" + rel, "line": function_line(texts[path], name)}
                if addr in out:
                    break
    return out


def link_errors(root):
    """Unresolved-symbol families from linked trial receipts (*blocker-ranking.json): family -> errors."""
    out = {"trials": [], "families": {}}
    for path in sorted((root / "work" / CLIENT / "shared-layouts").glob("*blocker-ranking*.json")):
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except (ValueError, OSError):
            continue
        out["trials"].append({"receipt": path.name, "link_exit": data.get("link_exit"),
                              "error_lines": data.get("error_lines"), "revision": str(data.get("receipt_revision", ""))[:10]})
        for row in data.get("ranked", []):
            entry = out["families"].setdefault(row["family"], {"symbols": [], "objects": [], "receipts": []})
            entry["symbols"] = sorted(set(entry["symbols"]) | {s["name"] for s in row.get("symbols", [])})
            entry["objects"] = sorted(set(entry["objects"]) | set(row.get("objects", [])))
            entry["receipts"].append(path.name)
    return out


def commit(root):
    head = root / ".git" / "HEAD"
    try:
        ref = head.read_text().strip()
        return (root / ".git" / ref[5:]).read_text().strip()[:10] if ref.startswith("ref: ") else ref[:10]
    except OSError:
        return ""


def announce_inactive(before, after, log=print):
    """Integration Digest (report only) for addresses that newly became inactive (exact) or draft native code."""
    rows = [(a, v) for a, v in after.items() if a not in before or (v[1] and not before[a][1])]
    if not rows:
        return
    from roc.integration_notify import post_section
    from roc.reports import inline_code
    rows.sort(key=lambda r: (not r[1][1], r[0]))
    lines = ["%s `%s` %s" % ("🟣 inactive" if v[1] else "🩷 draft", a, inline_code(v[0])) for a, v in rows[:12]]
    if len(rows) > 12:
        lines.append("+%d more" % (len(rows) - 12))
    section = {"name": "🟪 New Native Code · inactive (exact) / draft, not integrated",
               "value": "\n".join(lines)[:1024], "inline": False}
    post_section(None, "site", "rebuild", section, background=False)
    log("Integration digest: %d newly inactive/draft" % len(rows))


def build(root=ROOT, log=print, output=None, extra_reports=()):
    out = root / "rebuild" / CLIENT / "out"
    native_path = root / "work/integration/progress-native.json"
    server_native = set(json.loads(native_path.read_text())["addresses"]) if native_path.exists() else set()
    # Isolated linked module reports do not prove selection in the client.
    native = server_native
    names_path = out / "native-names.json"
    names = json.loads(names_path.read_text()) if names_path.exists() else {}
    db = sqlite3.connect("file:%s?mode=ro" % (root / "work/server.db").as_posix(), uri=True, timeout=30)
    try:
        scores = dict(db.execute("SELECT addr,score FROM funcs WHERE client=?", (CLIENT,)).fetchall())
        jobs = db.execute("SELECT id,user,model,unit,receipt,updated FROM integration_jobs WHERE state='accepted' "
                          "ORDER BY updated DESC").fetchall()
        leaders = db.execute("SELECT user,model,COUNT(*) FROM integration_credit WHERE client=? GROUP BY user,model "
                             "ORDER BY COUNT(*) DESC", (CLIENT,)).fetchall()
        # agent (Codex/Claude/...) claims: latest per unit; unexpired ones are live work
        now = datetime.now(timezone.utc).timestamp()
        activity, working = {}, {}
        for unit, user, worker, expires, state, addresses in db.execute(
                "SELECT unit,user,worker,expires,state,addresses FROM integration_claims WHERE client=? ORDER BY rowid",
                (CLIENT,)):
            live = expires > now and state == "claimed"
            activity[unit] = ["working" if live else state, user, worker]
            if live:
                for addr in json.loads(addresses or "[]"):
                    working[str(addr).lower().removeprefix("0x").zfill(8)] = [user, worker, unit]
    finally:
        db.close()
    # site's middle bucket: inactive (receipt-exact) or draft native code, not yet integrated
    inactive = inactive_code(root)
    owned = set(inactive)
    groups, functions = coverage(root, scores, native, owned)
    units = {job: unit for job, _, _, unit, _, _ in jobs}
    receipts = []
    daily = {}
    seen = set()
    for job, user, model, unit, receipt, updated in jobs:
        r = json.loads(receipt or "{}")
        key = r.get("job", job)
        if key in seen:
            continue
        seen.add(key)
        day = datetime.fromtimestamp(updated, ZoneInfo("America/New_York")).strftime("%Y-%m-%d")
        row = daily.setdefault(day, {"day": day, "gains": 0, "jobs": 0, "models": {}})
        gains = len(r.get("new_distinct", r.get("gains", [])))
        row["gains"] += gains
        row["jobs"] += 1
        series = row["models"].setdefault(model or "Unknown", {"gains": 0, "jobs": 0})
        series["gains"] += gains
        series["jobs"] += 1
        unit = ", ".join(dict.fromkeys(units.get(j, "") for j in r.get("merged_jobs", [job])))
        receipts.append({"job": key[:8], "user": user, "model": model, "units": unit[:120],
                         "gains": len(r.get("gains", [])), "distinct_gains": len(r.get("new_distinct", r.get("gains", []))), "owned_after": r.get("owned_after"),
                         "when": datetime.fromtimestamp(updated, timezone.utc).strftime("%Y-%m-%d %H:%M UTC")})
    shown = {a: names[a] for a in names if a in native or (names[a].get("score") or 0) >= 50}
    links_path = root / 'local/findings/2008-06/verification/native-source-links.json'
    sources = json.loads(links_path.read_text(encoding='utf-8')) if links_path.exists() else {}
    data = {"client": CLIENT, "updated": datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC"),
            "groups": groups,
            "commit": commit(root),
            "link_errors": link_errors(root),
            # unit -> [latest claim state ("working", "released", "parked: reason", ...), user, worker]
            "activity": activity,
            # addr -> [user, worker, unit] for unexpired agent claims
            "working": working,
            "native": sorted(native),
            "server_native": sorted(server_native),
            "owned": sorted(set(owned) & functions.keys()),
            "owned_waiting": sorted((set(owned) & functions.keys()) - native),
            "ownership_note": "Inactive / draft: native code exists (receipt-exact or draft) but is not integrated; link, runtime and server acceptance still pending.",
            # inactive native code: addr -> [decorated symbol, receipt-proven exact, receipt file]
            "inactive": {a: v for a, v in inactive.items() if a not in native},
            "sources": {a: value for a, value in sources.items() if a in native},
            # addr -> [readable name, decorated symbol, rebuilt score (100 = integrated)]
            "names": {a: [readable(v["symbol"]), v["symbol"], 100 if a in native else v.get("score")] for a, v in sorted(shown.items())},
            "daily": [daily[day] for day in sorted(daily)],
            "jobs": receipts[:100],
            "leaderboard": [{"user": u, "model": m, "native_credits": n} for u, m, n in leaders]}
    # addr -> {path, line} on the published work branch (site links these beside the mined source)
    listed = subprocess.run(["git", "ls-tree", "-r", "--name-only", "refs/remotes/origin/work", "--", "workspace/"],
                            cwd=root, capture_output=True, text=True).stdout.splitlines()
    published = {path.removeprefix("workspace/") for path in listed if path}
    data["inactive_sources"] = {a: {"path": "workspace/" + v[3][0], "line": v[3][1]}
                                for a, v in data["inactive"].items() if len(v) > 3 and v[3] and v[3][0] in published}
    follow_wrappers(root, data["inactive_sources"], {a: v[0] for a, v in data["inactive"].items()})
    # integrated functions without an indexed source: the object that owns them in the linked rebuild -> its source
    for addr, link in integrated_sources(root, native - set(data["sources"]), published).items():
        data["sources"][addr] = link
    follow_wrappers(root, {a: s for a, s in data["sources"].items() if "url" not in s},
                    {a: v[0] for a, v in data["names"].items()})
    for key, exact in (("native_inactive", True), ("native_draft", False)):
        hits = [functions[a] for a, v in data["inactive"].items() if v[1] == exact and a in functions]
        # separate from "groups": groups partition the code and are summed by the site
        data.setdefault("native_code", {})[key[7:]] = {"functions": len(hits), "bytes": sum(f["size"] for f in hits)}
    path = output or root / "docs/integration.json"
    previous_path = path if path.exists() else root / "docs/integration.json"
    previous = json.loads(previous_path.read_text(encoding="utf-8")) if previous_path.exists() else {}
    history = {row["day"]: row for row in previous.get("history", [])} if previous.get("client") == CLIENT else {}
    published_path = root / "docs/integration.json"
    if published_path != previous_path and published_path.exists():
        published = json.loads(published_path.read_text(encoding="utf-8"))
        if published.get("client") == CLIENT:
            history.update({row["day"]: row for row in published.get("history", [])})
    day = datetime.now(ZoneInfo("America/New_York")).strftime("%Y-%m-%d")
    history[day] = {"day": day, "groups": data["groups"], "native_code": data.get("native_code", {})}
    data["history"] = [history[day] for day in sorted(history)]
    atomic_json(path, data)
    if output is None and "inactive" in previous:  # first build has no baseline: don't announce everything
        announce_inactive(previous["inactive"], data["inactive"], log)
    log("Integration site data: %d integrated, %d named" % (len(native), len(data["names"])))
    return data


if __name__ == "__main__":
    build()

